const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let agendaMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),agendaDay='',agendaPersonal=true;
const key='elos-v1';let state;const initial=()=>({profile:'Melina',agreements:[],preferences:[],messages:[],drafts:[],quiz:{},planned:[]});
try{state=JSON.parse(localStorage.getItem(key))||initial()}catch{state=initial()}let page='inicio',prefTab='Melina',msgTab='Recebidas',flow=null,quizStep=0,quizAnswers=[];
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Não foi possível salvar neste navegador.')}}function me(){return state.profile}function other(){return me()==='Melina'?'Fabien':'Melina'}function uid(){return crypto.randomUUID()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
const menu=[['inicio','⌂','Nosso espaço'],['combinados','☷','Combinados'],['carinho','♡','O que me faz bem'],['comunicar','→','Quero comunicar'],['conversas','▱','Conversas'],['cuidar','✧','Cuidar de nós'],['agenda','▦','Nossa agenda'],['fe','✧','Fé e reflexão'],['parceiro','♡','Sobre meu parceiro'],['nos','⌒','Nós dois'],['iniciativas','','Meus gestos de cuidado'],['oracao','','Meus pedidos de oração'],['preferencias-parceiro','','Preferências do parceiro'],['enviadas','','Enviadas'],['recebidas','','Recebidas'],['agradar','','Fazer feliz'],['oracoes-casal','','Nossas orações']];
function prayerIcon(){return '<svg class="prayer-line-icon" viewBox="0 0 28 28" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m3 21 5-4 2-5 2-8c.3-1.5 2-1.5 2 0v11c0 2-1 4-2.5 5.5L7 25ZM25 21l-5-4-2-5-2-8c-.3-1.5-2-1.5-2 0v11c0 2 1 4 2.5 5.5L21 25Z"/><path d="m3 21 4 4M25 21l-4 4M8 17l2 2M20 17l-2 2"/></svg>'}
function coupleRings(){return '<svg class="rings-icon" viewBox="0 0 28 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><ellipse cx="10" cy="12" rx="7" ry="9" transform="rotate(-27 10 12)"/><ellipse cx="18" cy="12" rx="7" ry="9" transform="rotate(27 18 12)"/></svg>'}
const primaryNav=[['inicio','◌','Meu espaço'],['parceiro','♡','Meu parceiro'],['nos','⌒','Nós dois']];
function sectionFor(p){return ['inicio','carinho','iniciativas','oracao','fe','comunicar','enviadas','recebidas'].includes(p)?'inicio':['parceiro','preferencias-parceiro','agradar'].includes(p)?'parceiro':'nos'}
function sectionTabs(){const group=sectionFor(page),tabs=group==='inicio'?[['inicio','Visão geral'],['carinho','Meu jeito de receber amor'],['iniciativas','Meus gestos de cuidado'],['oracao','Meus pedidos de oração'],['comunicar','Quero conversar sobre algo difícil'],['enviadas','Mensagens enviadas'],['recebidas','Mensagens recebidas']]:group==='parceiro'?[['parceiro','Sobre '+other()],['preferencias-parceiro','O que importa e faz bem'],['agradar','Demonstrar carinho']]:[['nos','Nosso espaço'],['conversas','Conversas'],['combinados','Combinados'],['agenda','Agenda'],['oracoes-casal','Nossas orações']];return `<div class="section-tabs" aria-label="Seções de ${group==='inicio'?'Meu espaço':group==='parceiro'?'Meu parceiro':'Nós dois'}">${tabs.map(([p,t])=>`<a href="#${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${p==='oracao'||p==='oracoes-casal'?'<span class="prayer-small" aria-hidden="true">'+prayerIcon()+'</span> ':p==='nos'?coupleRings()+' ':''}${t}${p==='recebidas'?`<span class="badge message-count" data-message-badge ${unreadMessages().length?'':'hidden'}>${unreadMessages().length}</span>`:''}</a>`).join('')}</div>`}
function sharedAgendaCard(){const events=agendaEvents().filter(e=>!e.personal&&e.date.slice(0,10)>=dayKey(new Date())).slice(0,2);return `<section class="card shared-agenda-card"><span class="investment-action-icon">${investmentIcon('calendar')}</span><div><span class="eyebrow">NOSSO TEMPO JUNTOS</span><h2>Agenda do casal</h2>${events.length?events.map(e=>`<p><strong>${esc(new Date(e.date.length===10?e.date+'T12:00':e.date).toLocaleDateString('pt-BR',{day:'numeric',month:'short'}))}</strong> · ${esc(e.title.length>65?e.title.slice(0,65)+'…':e.title)} <small>${e.confirmed?'Confirmado':'Proposto'}</small></p>`).join(''):'<p>Compromissos, conversas e lembretes em um só lugar.</p>'}</div><a class="btn" href="#agenda">Ver nossa agenda →</a></section>`}
function specialSpace(){const photo=state.couplePhoto,prayers=(state.prayers||[]).filter(p=>p.shared&&p.status!=='archived'),moments=(state.moments||[]).slice().reverse(),bloom=moments.length>0;return `<section class="couple-heading"><div class="eyebrow">CLARA & RAFAEL</div><h1>O nosso lugar.</h1><p>As conversas, os planos e as lembranças que construímos juntos.</p></section><section class="wedding-verse" aria-label="Nosso versículo do casamento"><span class="eyebrow">NOSSO VERSÍCULO DO CASAMENTO</span><blockquote>“Dar-lhes-ei um só coração e um só caminho, para que me temam todos os dias, para seu bem e bem de seus filhos.”</blockquote><a href="https://www.sbb.org.br/biblia/ARA/JER.32" target="_blank" rel="noopener">Jeremias 32:39</a><small>Almeida Revista e Atualizada · © Sociedade Bíblica do Brasil</small></section>${coupleNextSteps()}${sharedAgendaCard()}<div class="grid pref-grid couple-shortcuts"><a class="card card-link" href="#conversas"><div><h2>Conversas</h2><p>Compartilhar, ouvir e responder.</p></div><span>→</span></a><a class="card card-link" href="#combinados"><div><h2>Nossos combinados</h2><p>Propostas e acordos construídos pelos dois.</p></div><span>→</span></a></div><div class="couple-layout"><section class="couple-memory">${photo?`<img src="${esc(photo.data)}" alt="${esc(photo.caption||'Uma memória especial do casal')}"><div class="couple-photo-overlay"><span class="eyebrow">UMA MEMÓRIA NOSSA</span><h2>${esc(photo.caption||'Um momento para guardar.')}</h2></div>`:`<div class="couple-photo-empty"><span class="couple-camera" aria-hidden="true">${investmentIcon('heart')}</span><h2>Um instante que é só de vocês.</h2><p>Escolham uma foto de um momento especial.</p>${btn('＋ Adicionar nossa foto','couple-photo','light')}</div>`}${photo?`<button class="couple-photo-edit" data-action="couple-photo">Trocar foto ou legenda</button>`:''}</section><section class="card couple-garden"><span class="eyebrow">O QUE CULTIVAMOS</span><div class="couple-plant" role="img" aria-label="Planta do casal, símbolo dos cuidados compartilhados"><span class="plant-halo"></span><span class="plant-stem"></span><span class="plant-leaf leaf-a"></span><span class="plant-leaf leaf-b"></span><span class="plant-leaf leaf-c"></span><span class="plant-leaf leaf-d"></span>${bloom?'<span class="plant-flower" aria-hidden="true">✿</span>':''}<span class="plant-pot"></span><span class="plant-soil"></span></div><h2>O que estamos cultivando</h2><p>Guardem pequenos momentos que fizeram bem a vocês.</p>${btn('Registrar um momento bom','good-moment','secondary')}<small>Sem pontos ou cobranças. Ela floresce com momentos reconhecidos e não perde folhas por falta de acesso.</small></section></div><div class="section-heading couple-section-heading"><h2>O que levamos em oração</h2><a class="text-btn" href="#oracoes-casal">Ver todos os pedidos →</a></div><div class="couple-prayers">${prayers.length?prayers.slice().reverse().slice(0,3).map(p=>`<details class="shared-prayer"><summary><span class="shared-prayer-icon" aria-hidden="true">${prayerIcon()}</span><div class="shared-prayer-title"><h3>${esc(p.title)}</h3><span>De ${esc(p.person)}</span></div><span class="badge">${p.status==='answered'?'Respondida':'Em oração'}</span><svg class="shared-prayer-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="shared-prayer-content"><p class="message-body">${esc(p.text)}</p></div></details>`).join(''):`<article class="card couple-empty-prayer"><span class="prayer-icon" aria-hidden="true">${prayerIcon()}</span><div><h3>Nenhum pedido compartilhado ainda.</h3></div><a class="btn secondary" href="#oracao">Adicionar pedido de oração →</a></article>`}</div>${moments.length?`<div class="section-heading couple-section-heading"><h2>Pequenas memórias de cuidado</h2></div><div class="couple-moments">${moments.slice(0,4).map(m=>`<article class="card"><span class="couple-quote" aria-hidden="true">“</span><p>${esc(m.text)}</p><small>${esc(m.person)} · ${esc(new Date(m.created).toLocaleDateString('pt-BR'))}</small></article>`).join('')}</div>`:''}`}
function coupleAction(a){if(a!=='couple-photo')return;modal(`<div class="eyebrow">UMA MEMÓRIA NOSSA</div><h2>Escolher nossa foto</h2><form id="couple-photo-form"><label class="field">Foto<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" ${state.couplePhoto?'':'required'}></label><label class="field">Uma legenda (opcional)<input type="text" name="caption" maxlength="160" value="${esc(state.couplePhoto?.caption||'')}" placeholder="Ex.: aquele dia à beira do lago"></label><p class="helper">A foto ficará visível aos dois perfis neste dispositivo. Não é enviada a um servidor.</p><div class="actions"><button class="btn">Guardar nossa memória</button></div><p class="helper" id="photo-error" role="status"></p></form>`);$('#couple-photo-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('photo'),caption=f.get('caption').trim(),error=$('#photo-error'),submit=e.target.querySelector('button');if(!file?.size){if(state.couplePhoto){state.couplePhoto.caption=caption;save();close();render()}return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000){error.textContent='Escolha uma imagem JPG, PNG ou WebP de até 15 MB.';return}submit.disabled=true;error.textContent='Preparando sua foto…';try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const scale=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82))};img.src=reader.result};reader.readAsDataURL(file)});const updated={...state,couplePhoto:{data,caption}};localStorage.setItem(key,JSON.stringify(updated));state=updated;close();render();toast('Memória guardada no espaço de vocês.')}catch{error.textContent='Não foi possível guardar esta foto. Tente uma imagem menor.';submit.disabled=false}}}

function personalHome(){return `<section class="clean-home"><div class="clean-page-head"><div><span class="eyebrow">MEU ESPAÇO</span><h1>Olá, ${esc(me())}.</h1></div></div>${messageNotice()}<div class="home-primary-actions">${btn('Preparar uma conversa','new-message')}<a class="btn secondary" href="#agradar">Escolher um gesto</a></div><div class="home-shortcuts">${[['carinho','♡','Meu jeito','O que importa e me faz bem'],['oracao',prayerIcon(),'Oração','Meus pedidos'],['conversas','<span class="chat-icon"></span>','Conversas','Recebidas, enviadas e rascunhos']].map(([href,icon,title,desc])=>`<a class="home-shortcut" href="#${href}"><span class="shortcut-icon" aria-hidden="true">${icon}</span><div><h2>${title}</h2><p>${desc}</p></div><span class="shortcut-arrow" aria-hidden="true">→</span></a>`).join('')}</div></section>`}

function partnerHome(){return head('MEU PARCEIRO',`Sobre ${other()}`,'Conhecer seu jeito. Escolher um cuidado.')+`<div class="partner-paths about-paths"><article class="partner-path"><span class="partner-path-icon">${investmentIcon('heart')}</span><span class="eyebrow">CONHECER</span><h2>O que importa e faz bem</h2><p>Conheça o que é importante e o que faz bem para ${other()}.</p><a class="btn" href="#preferencias-parceiro">Conhecer ${other()} →</a></article><article class="partner-path partner-path-soft"><span class="partner-path-icon">${investmentIcon('plus')}</span><span class="eyebrow">DEMONSTRAR CARINHO</span><h2>Demonstrar carinho</h2><p>Uma mensagem, um convite ou uma ideia de presente, escolhidos com carinho.</p><a class="btn" href="#agradar">Escolher um gesto →</a></article></div>`}
let gestureTab='Agora';
function makeHappy(){const plans=state.planned.filter(p=>p.person===me()),ideas=plans.filter(p=>!p.date),reminders=plans.filter(p=>p.date).sort((a,b)=>new Date(a.date)-new Date(b.date));const tabs=`<div class="tabbar gesture-tabs" role="group" aria-label="Demonstrar carinho">${['Agora','Ideias guardadas','Lembretes'].map(t=>`<button class="tab ${gestureTab===t?'active':''}" aria-pressed="${gestureTab===t}" data-action="gesture-tab:${t}">${t}</button>`).join('')}</div>`;let content='';if(gestureTab==='Agora'){const idea=suggestion();content=`<div class="gesture-options">${[['Mensagem','Dizer algo bom ou agradecer.','happy-message','heart','Escrever mensagem'],['Convite','Propor um tempo juntos.','connection-invite','calendar','Fazer convite'],['Presente','Escolher algo com significado.','happy-gift','plus','Pensar em um presente']].map(([title,desc,action,icon,label])=>`<article class="gesture-option"><span class="investment-action-icon">${investmentIcon(icon)}</span><h2>${title}</h2><p>${desc}</p>${btn(label,action,'secondary')}</article>`).join('')}</div><section class="card gesture-suggestion"><div><span class="eyebrow">UMA IDEIA PARA HOJE</span><p>${esc(idea.text)}</p></div>${btn('Guardar ideia','plan-home','secondary')}</section>`}else if(gestureTab==='Ideias guardadas'){content=`<div class="gesture-toolbar">${btn('+ Guardar uma ideia','gesture-new-idea','secondary')}${btn('+ Planejar um gesto','add-intention','secondary')}</div><div class="stack">${ideas.map(p=>`<article class="card gesture-saved"><p>${esc(p.text)}</p><button class="text-btn" data-action="delete-plan:${p.id}">Remover</button></article>`).join('')||'<div class="card empty">Suas ideias guardadas aparecem aqui.</div>'}</div>${initiatives()}`}else{content=`<div class="gesture-toolbar">${btn('+ Adicionar lembrete','reminder','secondary')}<a class="text-btn" href="#agenda">Ver agenda →</a></div><div class="stack">${reminders.map(p=>`<article class="card gesture-saved"><div><h2>${esc(p.text)}</h2><p>${esc(new Date(p.date).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}))}</p></div><button class="text-btn" data-action="delete-plan:${p.id}">Remover</button></article>`).join('')||'<div class="card empty">Nenhum lembrete ainda.</div>'}</div><p class="helper">Os lembretes ficam no app, sem notificações no celular.</p>`}return `<section class="gesture-page"><div class="clean-page-head"><div><span class="eyebrow">SOBRE ${esc(other().toUpperCase())}</span><h1>Demonstrar carinho</h1></div></div>${tabs}${content}</section>`}
function gestureAction(a,id){if(a==='gesture-tab'){gestureTab=id;render()}if(a==='gesture-new-idea'){modal(`<h2>Guardar uma ideia</h2><form id="gesture-idea-form"><label class="field">O que gostaria de fazer?<textarea name="text" required maxlength="2000" placeholder="Ex.: preparar um café da manhã juntos."></textarea></label><div class="actions"><button class="btn">Guardar ideia</button></div></form>`);$('#gesture-idea-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;state.planned.push({id:uid(),person:me(),text});save();close();render();toast('Ideia guardada.')}}}

function myCommunicationCards(){return `<div class="section-heading"><h2>Minhas conversas</h2></div><div class="partner-paths"><article class="partner-path partner-path-soft"><span class="partner-path-icon"><span class="chat-icon"></span></span><h2>Quero conversar sobre algo difícil</h2><p>Entender o que aconteceu, nomear o que senti e escrever.</p>${btn('Organizar o que senti →','partner-help')}</article><article class="partner-path"><span class="partner-path-icon">${investmentIcon('calendar')}</span><h2>Mensagens enviadas</h2><p>Mensagens, respostas e assuntos que ainda pedem atenção.</p><a class="btn" href="#enviadas">Ver mensagens enviadas →</a></article><article class="partner-path"><span class="partner-path-icon">${investmentIcon('heart')}</span><h2>Mensagens recebidas <span class="badge message-count" data-message-badge ${unreadMessages().length?'':'hidden'}>${unreadMessages().length}</span></h2><p>As mensagens de ${other()}, com data e espaço para responder.</p><a class="btn" href="#recebidas">Ver mensagens recebidas →</a></article></div>`}
function receivedMessages(){const list=state.messages.filter(m=>latestReceived(m)).slice().sort((a,b)=>(b.created||0)-(a.created||0));return head('MEU ESPAÇO','Mensagens recebidas',`Mensagens e respostas de ${other()}. Clique para abrir.`)+`<div class="stack">${list.map(m=>`<details data-read-message="${m.id}" class="sent-message ${m.awaitingReplyFrom===me()||m.status==='Enviada'?'waiting':'replied'}"><summary><span class="sent-symbol" aria-hidden="true">↩</span><div class="sent-summary">${isUnread(m)?'<span class="badge message-count" data-new-message>Nova</span>':''}<span class="sent-date">${m.created?esc(new Date(m.created).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})):'Data não registrada'}</span><h3>${esc(((m.text.split('\n')[0]||'Mensagem').slice(0,100)+(m.text.split('\n')[0].length>100?'…':'')))}</h3><span data-reading-label class="sent-status ${m.awaitingReplyFrom===me()||m.status==='Enviada'?'waiting':'replied'}">${m.awaitingReplyFrom===me()||m.status==='Enviada'?'Sua resposta é bem-vinda':'Conversa em andamento'}</span></div><span class="sent-chevron">⌄</span></summary><div class="sent-detail"><p class="message-body">${esc(m.text)}</p>${threadHistory(m)}<div class="actions">${btn('Enviar resposta','thread-reply:'+m.id)}${m.type!=='Algo bom'&&m.to===me()?btn('Preciso de um tempo','respond:'+m.id+':tempo','secondary'):''}</div></div></details>`).join('')||'<div class="card empty">Nenhuma mensagem recebida por enquanto.</div>'}</div>`}
function avoidPreferences(){const mine=prefTab===me(),list=(state.avoidances||[]).filter(p=>p.person===prefTab&&(mine||p.shared!==false));return `<section class="preference-panel concern-panel"><div class="preference-panel-head"><span class="panel-symbol" aria-hidden="true">◌</span><h2>O que me incomoda</h2><span class="preference-count">${list.length}</span></div><div class="preference-items">${list.map(p=>`<article class="preference-item concern-item">${mine?`<span class="visibility-label">${p.shared===false?'Só no meu perfil':'Compartilhado'}</span>`:''}<p class="preference-quote">${esc(p.text)}</p>${p.need?`<div class="concern-detail"><span>Faz falta</span><p>${esc(p.need)}</p></div>`:''}${p.request?`<div class="request-detail"><span>Meu pedido <small>· para conversar</small></span><p>${esc(p.request)}</p></div>`:''}${mine?`<div class="preference-item-actions">${btn('Editar','concern-edit:'+p.id,'secondary')}${p.request?btn('Preparar mensagem','concern-message:'+p.id,'secondary'):''}${btn('Remover','avoid-remove:'+p.id,'text-btn')}</div>`:''}</article>`).join('')||`<div class="preference-empty"><span aria-hidden="true">◌</span><p>${mine?'Quer sinalizar algo?':'Nada compartilhado por aqui ainda.'}</p></div>`}</div>${mine?btn('+ Adicionar incômodo','concern-new','panel-add secondary'):''}</section>`}

let concernDraft=null;
function concernForm(p=null){concernDraft={id:p?.id,text:p?.text||'',need:p?.need||'',request:p?.request||'',shared:p? p.shared!==false:false};modal(`<div class="eyebrow">PREFERÊNCIAS, INCÔMODOS E PEDIDOS</div><h2>O que você gostaria de sinalizar?</h2><p>Você pode guardar apenas o incômodo. Se quiser fazer um pedido, vamos esclarecer o que deseja mudar sem apagar o que sente.</p><form id="concern-form"><label class="field">O que me incomoda<textarea name="text" required maxlength="1500" placeholder="Ex.: não gosto que você jogue bola todos os domingos.">${esc(concernDraft.text)}</textarea></label><details class="concern-guide" ${p?.request||p?.need?'open':''}><summary>Quero ajuda para formular um pedido</summary><p>O que você gostaria que fosse diferente? Mais tempo juntos e reservar dois domingos por mês são pedidos diferentes. Escolha o que representa você.</p><label class="field">O que faz falta ou é importante para mim? (opcional)<textarea name="need" maxlength="1500" placeholder="Ex.: sinto falta de passar tempo com você aos domingos.">${esc(concernDraft.need)}</textarea></label><div class="note"><strong>Dois caminhos possíveis</strong><p><b>Abrir uma conversa:</b> “Gostaria de passar mais tempo com você aos domingos. Como podemos organizar isso?”</p><p><b>Propor algo concreto:</b> “Podemos reservar pelo menos dois domingos por mês para ficarmos juntos e combinar quais?”</p><small>São exemplos. A escolha de frequência e a proposta são suas.</small></div><label class="field">O que eu gostaria de pedir? (opcional)<textarea name="request" maxlength="2000" placeholder="Escreva seu pedido ou proposta. Pode ser diferente dos exemplos.">${esc(concernDraft.request)}</textarea></label><p class="helper">Ajuda guiada por perguntas e exemplos, sem IA conectada. O app não deduz sua necessidade nem escolhe um pedido por você.</p></details><label class="check-label"><input type="checkbox" name="shared" ${concernDraft.shared?'checked':''}>Mostrar este registro completo a ${other()} na minha área de preferências.</label><p class="helper">Sem marcar, o registro não aparece na área compartilhada. Este protótipo não tem senha: quem usa o navegador pode acessar os dois perfis.</p><div class="actions"><button class="btn" name="intent" value="save">Revisar registro →</button></div></form>`);$('#concern-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);concernDraft={...concernDraft,text:f.get('text').trim(),need:f.get('need').trim(),request:f.get('request').trim(),shared:f.has('shared')};if(!concernDraft.text)return;concernReview()}}
function concernReview(){const d=concernDraft;modal(`<div class="eyebrow">REVISAR ANTES DE GUARDAR</div><h2>Isso representa o que você quer dizer?</h2><div class="concern-card"><h3>O que me incomoda</h3><p class="message-body">${esc(d.text)}</p>${d.need?`<h3>O que faz falta</h3><p class="message-body">${esc(d.need)}</p>`:''}${d.request?`<h3>Meu pedido</h3><p class="message-body">${esc(d.request)}</p>`:''}</div><p class="note">${d.shared?'O registro completo ficará visível para '+other()+' nas suas preferências.':'O registro não será mostrado na área compartilhada.'} Nenhuma mensagem será enviada. ${d.request?'Este pedido ainda não é um combinado.':''}</p><div class="actions">${btn('Editar','concern-back','secondary')}${btn(d.shared?'Salvar e compartilhar registro':'Salvar sem compartilhar','concern-save')}</div>`)}
function concernAction(a,id){const p=(state.avoidances||[]).find(p=>p.id===id&&p.person===me());if(a==='concern-new')concernForm();if(a==='concern-edit'&&p)concernForm(p);if(a==='concern-back'&&concernDraft)concernForm(concernDraft);if(a==='concern-save'&&concernDraft){state.avoidances??=[];const d=concernDraft,index=state.avoidances.findIndex(p=>p.id===d.id&&p.person===me()),record={...d,id:d.id||uid(),person:me()};if(index>=0)state.avoidances[index]=record;else state.avoidances.push(record);save();close();render();toast(d.shared?'Registro compartilhado nas suas preferências.':'Registro salvo sem compartilhar.');concernDraft=null}if(a==='concern-message'&&p?.request){close();flow={step:4,type:'Uma necessidade',answers:[p.text,'',p.need,p.request],category:'Uma necessidade ou desejo',final:'Quero conversar sobre algo que me incomoda: '+p.text+(p.need?'\n\nO que faz falta para mim: '+p.need:'')+'\n\nO que gostaria de pedir: '+p.request};page='comunicar';location.hash='comunicar';render();window.scrollTo(0,0)}}

function aboutAction(a,id){if(a==='happy-message'){page='comunicar';location.hash=page;flow={step:0,type:'Algo bom',answers:[],category:'Reconhecimento'};render()}if(a==='happy-gift'){modal(`<h2>Um presente com significado</h2><p>O que ${other()} contou gostar? Pense em uma lembrança ligada a isso: um livro, uma comida preferida, um bilhete ou algo feito por você.</p><p>Você também pode perguntar o que seria bem-vindo, sem precisar comprar nada.</p><div class="actions">${btn('Ver preferências','gift-preferences','secondary')}${btn('Guardar minha ideia','gift-save')}</div>`)}if(a==='gift-preferences'){close();go('preferencias-parceiro')}if(a==='gift-save'){modal(`<h2>Minha ideia de presente</h2><form id="gift-form"><label class="field">O que pensei?<textarea name="text" required maxlength="1000"></textarea></label><div class="actions"><button class="btn">Guardar ideia</button></div></form>`);$('#gift-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;state.planned.push({id:uid(),person:me(),text:'Ideia de presente: '+text});save();close();render();toast('Ideia guardada nos seus registros.')}}if(a==='avoid-new'){modal(`<h2>O que prefiro evitar</h2><form id="avoid-form"><label class="field">Minha preferência<textarea name="text" required maxlength="1500" placeholder="Ex.: prefiro não receber surpresas em público."></textarea></label><p class="helper">Será visível para o parceiro no seu perfil de preferências.</p><div class="actions"><button class="btn">Salvar preferência</button></div></form>`);$('#avoid-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;state.avoidances??=[];state.avoidances.push({id:uid(),person:me(),text});save();close();render()}}if(a==='avoid-remove'){state.avoidances=(state.avoidances||[]).filter(p=>p.id!==id||p.person!==me());save();render()}}

function threadHistory(m){const entries=[...(m.response?[{person:m.to,text:m.response,created:m.respondedAt||null}]:[]),...(m.replies||[])];return entries.length?`<div class="thread-history"><div class="eyebrow">CONTINUAÇÃO DA CONVERSA</div>${entries.map(r=>`<div class="thread-entry ${r.person===me()?'mine':''}"><small>${r.person===me()?'Você':esc(r.person)}${r.created?' · '+esc(new Date(r.created).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})):''}</small><p class="message-body">${esc(r.text)}</p></div>`).join('')}</div>`:''}
function threadAction(a,id){if(a!=='thread-reply')return;const m=state.messages.find(m=>m.id===id&&(m.from===me()||m.to===me()));if(!m)return;modal(`<div class="eyebrow">CONTINUAR A CONVERSA</div><h2>Enviar resposta a ${other()}</h2><p>Seu texto ficará no histórico deste assunto.</p><form id="thread-form"><label class="field">Minha resposta<textarea name="text" required maxlength="5000" placeholder="Escreva o que gostaria de dizer."></textarea></label><div class="actions"><button class="btn">Enviar resposta</button></div><p class="helper">Envio simulado neste navegador. O assunto volta a aguardar resposta.</p></form>`);$('#thread-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;m.replies??=[];m.replies.push({id:uid(),person:me(),text,created:Date.now()});m.resolution=null;m.status='Enviada';m.awaitingReplyFrom=other();save();close();render();toast('Resposta registrada no histórico deste assunto.')}}

function sentStatus(m){if(m.awaitingReplyFrom)return {code:m.awaitingReplyFrom===me()?'replied':'waiting',label:m.awaitingReplyFrom===me()?'Resposta recebida · sua vez':'Aguardando resposta',icon:m.awaitingReplyFrom===me()?'↩':'◷'};if(m.resolution==='resolved')return {code:'resolved',label:'Concluído para mim',icon:'✓'};if(m.resolution==='unresolved')return {code:'unresolved',label:'Ainda precisamos conversar',icon:'!'};if(m.reconnected)return {code:'replied',label:'Conversa retomada · avaliar',icon:'↩'};if(m.response||m.inviteStatus||m.status==='Respondida')return {code:'replied',label:'Resposta recebida · avaliar',icon:'↩'};return {code:'waiting',label:'Aguardando resposta',icon:'◷'}}
function sentMessages(){const list=state.messages.filter(m=>m.from===me()).slice().sort((a,b)=>(b.created||0)-(a.created||0));return head('MEU PARCEIRO','Mensagens enviadas',`Suas mensagens para ${other()}, organizadas por data.`,btn('+ Preparar mensagem','new-message'))+`<div class="sent-legend"><span class="sent-status resolved">✓ Concluído para mim</span><span class="sent-status waiting">◷ Aguardando resposta</span><span class="sent-status unresolved">Ainda precisamos conversar</span><span class="sent-status replied">↩ Resposta recebida</span></div><div class="stack">${list.map(m=>{const st=sentStatus(m),preview=m.text.split('\n').find(t=>t.trim())||'Mensagem',date=m.created?new Date(m.created).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Data não registrada';return `<details data-read-message="${m.id}" class="sent-message ${st.code}"><summary><span class="sent-symbol" aria-hidden="true">${st.icon}</span><div class="sent-summary"><span class="sent-date">${esc(date)} · ${esc(m.category||m.type||'Mensagem')}</span><h3>${esc(preview.length>95?preview.slice(0,95)+'…':preview)}</h3><span class="sent-status ${st.code}">${st.label}</span></div><span class="sent-chevron" aria-hidden="true">⌄</span></summary><div class="sent-detail"><div class="eyebrow">MINHA MENSAGEM</div><p class="message-body">${esc(m.text)}</p>${threadHistory(m)}<div class="actions">${btn('Enviar resposta','thread-reply:'+m.id)}</div>${m.returnAt?`<p class="helper">Retomada proposta: ${esc(new Date(m.returnAt).toLocaleString('pt-BR'))}</p>`:''}<div class="sent-resolution"><p class="helper">Como este assunto está para você? A marcação é pessoal e não significa que o outro concordou.</p><div class="actions">${btn('✓ Concluído para mim','sent-resolved:'+m.id,'secondary')}${btn('Ainda precisamos conversar','sent-unresolved:'+m.id,'secondary')}${m.resolution?btn('Retirar minha marcação','sent-reset:'+m.id,'secondary'):''}</div></div></div></details>`}).join('')||`<div class="card empty"><h3>Você ainda não enviou mensagens.</h3><p>Quando compartilhar uma mensagem, ela aparecerá aqui com a data.</p>${btn('Preparar minha primeira mensagem','new-message','secondary')}</div>`}</div><p class="privacy">Uma resposta não encerra o assunto automaticamente. Verde e vermelho refletem sua marcação; não são avaliações da IA.</p>`}
function partnerAction(a,id){if(a==='partner-help'){page='comunicar';location.hash='comunicar';flow={step:0,type:'Algo difícil',answers:[],category:'Ainda estou entendendo'};render();window.scrollTo(0,0)}if(a==='emotion-word'){const input=$('#flow-input');if(!input)return;input.value=input.value.trim()?input.value.trim()+', '+id:id;input.focus()}if(['sent-resolved','sent-unresolved','sent-reset'].includes(a)){const m=state.messages.find(m=>m.id===id&&m.from===me());if(!m)return;m.awaitingReplyFrom=null;m.resolution=a==='sent-resolved'?'resolved':a==='sent-unresolved'?'unresolved':null;save();render();toast('Sua marcação foi atualizada.')}}

function investmentIcon(kind){const paths={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',plus:'M12 5v14M5 12h14',calendar:'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[kind]||paths.heart}"/></svg>`}
function personalInvestment(){const list=(state.initiatives||[]).filter(g=>g.person===me()),reminders=state.planned.filter(p=>p.person===me()&&p.date),total=list.reduce((n,g)=>n+(g.logs||[]).filter(t=>t>=initiativePeriod('mes')).length,0),active=list.filter(g=>!g.paused).length;return head('MEU ESPAÇO','Meus gestos de cuidado','Pequenos gestos, escolhidos por você.')+`<div class="investment-stats" ${!list.length&&!reminders.length?'hidden':''}><div><span class="investment-stat-icon">${investmentIcon('heart')}</span><div><strong>${active}</strong><span>intenções ativas</span></div></div><div><span class="investment-stat-icon">${investmentIcon('check')}</span><div><strong>${total}</strong><span>gestos neste mês</span></div></div><div><span class="investment-stat-icon">${investmentIcon('calendar')}</span><div><strong>${reminders.length}</strong><span>lembretes pessoais</span></div></div></div><div class="investment-actions"><button class="investment-action primary-action" data-action="add-intention"><span class="investment-action-icon">${investmentIcon('plus')}</span><h3>Criar uma iniciativa</h3><p>Escolha um gesto e a frequência.</p><span class="investment-action-link">Começar <span>→</span></span></button><button class="investment-action" ${!list.length?'hidden':''} data-action="investment-log"><span class="investment-action-icon">${investmentIcon('check')}</span><h3>Registrar um gesto</h3><p>Conte um cuidado que você realizou.</p><span class="investment-action-link">Escolher iniciativa <span>→</span></span></button><button class="investment-action" data-action="reminder"><span class="investment-action-icon">${investmentIcon('calendar')}</span><h3>Adicionar lembrete</h3><p>Reserve uma data para lembrar.</p><span class="investment-action-link">Escolher data <span>→</span></span></button></div>${!list.length?`<section class="investment-suggestions"><div class="section-heading"><h2>Um pequeno cuidado pode começar hoje.</h2><span class="mini-note">Escolha uma ideia e personalize a frequência para sua rotina.</span></div><div class="investment-template-grid">${[['jantar','Propor um jantar','1 vez por mês','calendar'],['carinho','Um gesto de carinho','3 vezes por mês','heart'],['atencao','Um momento de atenção','1 vez por dia','clock']].map(([id,t,f,icon])=>`<button class="investment-template" data-action="investment-template:${id}"><span>${investmentIcon(icon)}</span><div><strong>${t}</strong><small>${f}</small></div><span aria-hidden="true">+</span></button>`).join('')}</div></section>`:''}${initiatives()}<div class="section-heading"><h2>Meus lembretes</h2><a class="text-btn" href="#agenda">Ver agenda →</a></div><div class="investment-goals">${reminders.map(p=>`<article class="card investment-reminder"><span class="investment-action-icon">${investmentIcon('calendar')}</span><h3>${esc(p.text)}</h3><p>${esc(new Date(p.date).toLocaleDateString('pt-BR',{day:'numeric',month:'long'}))} · ${esc(new Date(p.date).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}</p><button class="text-btn" data-action="delete-plan:${p.id}">Remover lembrete</button></article>`).join('')||`<button class="investment-add-reminder" data-action="reminder">${investmentIcon('plus')}<span>Adicionar meu primeiro lembrete</span></button>`}</div><details class="investment-privacy"><summary>Sobre seus registros e privacidade</summary><p>São iniciativas pessoais, sem cobrança de retribuição. A contagem descreve seus registros, não a qualidade da relação. No protótipo, os perfis podem ser trocados no mesmo dispositivo, sem senha.</p></details>`}

function prayerPage(shared=false){const list=(state.prayers||[]).filter(p=>shared?p.shared&&p.status!=='archived':p.person===me());return `<section class="clean-prayers"><div class="clean-page-head"><div><span class="eyebrow">${shared?'NÓS DOIS':'MEU ESPAÇO'}</span><h1>${shared?'Nossos pedidos de oração':'Meus pedidos de oração'}</h1></div>${shared?'':btn('+ Novo pedido','prayer-new')}</div><div class="prayer-list">${list.length?list.slice().reverse().map(p=>`<details class="prayer-item"><summary><div class="prayer-summary"><h2>${esc(p.title)}</h2><div class="meta"><span class="badge">${p.status==='answered'?'Respondido':p.status==='archived'?'Arquivado':'Em oração'}</span><span class="prayer-visibility">${p.shared?'Compartilhado':'Só no meu perfil'}</span></div></div><svg class="prayer-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="prayer-content"><p class="message-body">${esc(p.text)}</p><small>${shared?esc(p.person)+' · ':''}${esc(new Date(p.created).toLocaleDateString('pt-BR'))}</small>${p.person===me()?`<div class="prayer-card-actions">${btn('Editar','prayer-edit:'+p.id,'secondary')}${btn(p.shared?'Retirar compartilhamento':'Compartilhar','prayer-share:'+p.id,'secondary')}<details class="prayer-more"><summary>Mais opções</summary><div class="actions">${btn(p.status==='answered'?'Marcar como em oração':'Marcar como respondido','prayer-answer:'+p.id,'secondary')}${btn(p.status==='archived'?'Restaurar':'Arquivar','prayer-archive:'+p.id,'secondary')}</div></details></div>`:''}</div></details>`).join(''):`<div class="prayer-empty"><span aria-hidden="true">${prayerIcon()}</span><p>${shared?'Nenhum pedido compartilhado ainda.':'Nenhum pedido ainda.'}</p></div>`}</div><div class="prayer-page-bottom">${shared?'':'<a class="text-btn" href="#fe">Leituras e reflexões →</a>'}<details class="prayer-sharing-info"><summary>Sobre o compartilhamento</summary><p>Você escolhe quais pedidos aparecem em “Nós dois”. Retirar o compartilhamento não apaga o que já foi lido.</p><p>Este protótipo não tem senha: quem usa o navegador pode acessar os dois perfis.</p></details></div></section>`}

function prayerAction(a,id){const p=(state.prayers||[]).find(p=>p.id===id&&p.person===me());if(a==='prayer-new'||a==='prayer-edit'){if(a==='prayer-edit'&&!p)return;modal(`<div class="eyebrow">MINHA ORAÇÃO</div><h2>${p?'Editar pedido':'O que deseja levar em oração?'}</h2><form id="prayer-form"><label class="field">Assunto<input type="text" name="title" required maxlength="160" value="${esc(p?.title||'')}" placeholder="Ex.: nossa família"></label><label class="field">Meu pedido<textarea name="text" required maxlength="5000">${esc(p?.text||'')}</textarea></label><p class="helper">${p?.shared?'Este pedido está compartilhado. Ao salvar, o texto atualizado ficará visível ao parceiro.':'Este pedido não é enviado ao parceiro. No protótipo, quem usa este navegador pode acessar os dois perfis. Depois de salvar, você escolhe se deseja compartilhar.'}</p><div class="actions"><button class="btn">Salvar pedido</button></div></form>`);$('#prayer-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),text=f.get('text').trim();if(!title||!text)return;if(p){p.title=title;p.text=text}else{state.prayers??=[];state.prayers.push({id:uid(),person:me(),title,text,shared:false,status:'active',created:Date.now()})}save();close();render();toast('Pedido salvo.')}}if(!p)return;if(a==='prayer-share'){if(p.shared){p.shared=false;save();render();toast('Compartilhamento retirado.')}else modal(`<h2>Compartilhar este pedido?</h2><p>“${esc(p.title)}” e o texto completo aparecerão em “Nós dois → Nossas orações”, visíveis para ${other()}.</p><div class="actions">${btn('Confirmar compartilhamento','prayer-confirm:'+p.id)}</div>`)}if(a==='prayer-confirm'){p.shared=true;save();close();render();toast('Pedido compartilhado na área do casal.')}if(a==='prayer-answer'){p.status=p.status==='answered'?'active':'answered';save();render()}if(a==='prayer-archive'){p.status=p.status==='archived'?'active':'archived';save();render()}}

function go(p){page=p;if(p==='comunicar')flow=null;location.hash=p;render();window.scrollTo(0,0)}window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(menu.some(x=>x[0]===p)&&p!==page){page=p;render()}});
function render(){ if(page==='iniciativas'||page==='cuidar'){gestureTab=page==='iniciativas'?'Ideias guardadas':'Agora';page='agradar';history.replaceState(null,'','#agradar');} $('footer').hidden=page==='nos'; $('#profile').value=me();const group=sectionFor(page);$('#nav').innerHTML=primaryNav.map(([id,icon,name])=>`<a href="#${id}" class="${group===id?'active':''}" ${group===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${id==='nos'?coupleRings():icon}</span>${id==='parceiro'?'Sobre '+other():name}${id==='inicio'?`<span class="spacer badge message-count" data-message-badge ${unreadMessages().length?'':'hidden'}>${unreadMessages().length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=primaryNav.find(x=>x[0]===group)[2];if(page==='carinho')prefTab=me();if(page==='preferencias-parceiro')prefTab=other();if(page==='enviadas')msgTab='Enviadas';if(page==='recebidas')msgTab='Recebidas';const views={inicio:personalHome,parceiro:partnerHome,nos:specialSpace,iniciativas:personalInvestment,oracao:()=>prayerPage(false),'oracoes-casal':()=>prayerPage(true),'preferencias-parceiro':preferences,enviadas:messages,recebidas:messages,agradar:makeHappy,combinados:agreements,carinho:preferences,comunicar:communicate,conversas:messages,cuidar:care,agenda:agenda,fe:biblical};$('#app').innerHTML=(!['inicio','parceiro','nos'].includes(page)?`<a class="back-to-space" href="#${group}">← Voltar para ${group==='inicio'?'meu espaço':group==='parceiro'?'Sobre '+other():'Nós dois'}</a>`:'')+(views[page]||personalHome)();bind();bindMessageReading();if(page==='agenda')$('#agenda-personal').onchange=e=>{agendaPersonal=e.target.checked;render()};}
function latestReceived(m,person=me()){const list=[];if(m.to===person)list.push({token:'initial:'+m.id,time:m.created||0});if(m.from===person&&m.response)list.push({token:'response:'+m.response+':'+(m.respondedAt||''),time:m.respondedAt||m.created||0});for(const r of m.replies||[])if(r.person!==person)list.push({token:'reply:'+(r.id||r.created+':'+r.text),time:r.created||0});return list.sort((a,b)=>a.time-b.time).at(-1)||null}
function isUnread(m){const latest=latestReceived(m);return !!latest&&m.readBy?.[me()]!==latest.token}
function unreadMessages(){return state.messages.filter(isUnread)}
function messageNotice(){const n=unreadMessages().length,pending=incoming().filter(m=>!isUnread(m)).length;if(!n&&!pending)return '';return `<a class="message-notice compact-notice" href="#recebidas"><span class="notice-icon" aria-hidden="true"><span class="chat-icon"></span></span><strong>${n?n+' '+(n===1?'nova mensagem':'novas mensagens')+' de '+esc(other()):pending+' '+(pending===1?'conversa aguarda':'conversas aguardam')+' sua resposta'}</strong><span class="notice-link">${n?'Ler':'Ver'} <span aria-hidden="true">→</span></span></a>`}

function refreshMessageBadges(){document.querySelectorAll('[data-message-badge]').forEach(el=>{const n=unreadMessages().length;el.textContent=n;el.hidden=!n})}
function bindMessageReading(){document.querySelectorAll('details[data-read-message]').forEach(el=>el.addEventListener('toggle',()=>{if(!el.open)return;const m=state.messages.find(m=>m.id===el.dataset.readMessage),latest=m&&latestReceived(m);if(!latest)return;m.readBy??={};m.readBy[me()]=latest.token;save();refreshMessageBadges();const badge=el.querySelector('[data-new-message]');if(badge)badge.hidden=true;const pending=el.querySelector('[data-reading-label]');if(pending)pending.textContent=incoming().some(x=>x.id===m.id)?'Aguardando sua resposta':'Conversa em andamento'}))}

function incoming(){return state.messages.filter(m=>m.awaitingReplyFrom?m.awaitingReplyFrom===me():m.to===me()&&m.status==='Enviada')}
function head(ey,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}function btn(t,fn,cls=''){return `<button class="btn ${cls}" data-action="${fn}">${t}</button>`}
function home(){const n=incoming().length;return `<div class="welcome"><div><div class="eyebrow">O NOSSO ESPAÇO</div><h1>Olá, ${me()}. Como você está?</h1><p class="sub">Nem sempre é fácil encontrar as palavras. Podemos começar com calma.</p></div><span class="date">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">ENTRE O SENTIR E O DIZER</div><h2>Uma ponte começa<br>com uma pequena abertura.</h2><p>Organize o que sente, encontre suas palavras e respeite o tempo de vocês.</p>${btn('Quero comunicar algo <span class="arrow">→</span>','new-message')}</div><div class="art" aria-hidden="true"><span class="spark">✧</span><span class="arch"></span><span class="arch two"></span><span class="leaf"></span><span class="leaf two"></span></div></section><div class="grid three"><article class="card"><div class="card-icon">☷</div><h3>O que combinamos</h3><p>Acordos claros, construídos e aceitos pelos dois.</p><a class="card-link" href="#combinados">${state.agreements.filter(a=>a.accepted.length===2).length} combinados em prática <span>→</span></a></article><article class="card"><div class="card-icon peach">♡</div><h3>O que nos aproxima</h3><p>Descubram os pequenos gestos que fazem diferença.</p><a class="card-link" href="#carinho">Conhecer nossas preferências <span>→</span></a></article><article class="card"><div class="card-icon" aria-hidden="true"><span class="chat-icon"></span></div><h3>Espaço para ouvir</h3><p>Uma conversa pode começar sem precisar resolver tudo agora.</p><a class="card-link" href="#conversas">${n?n+' mensagem para você':'Ver nossas conversas'} <span>→</span></a></article></div><div class="section-heading"><h2>Pequenos cuidados, todos os dias</h2><a class="text-btn" href="#cuidar">Ver ideias →</a></div><div class="grid two-col"><article class="card daily"><div class="daily-symbol">✿</div><div><span class="badge warm">UM CONVITE PARA HOJE</span><h3>Carinho também é presença.</h3><p>${esc(suggestion().text)}</p>${btn('Guardar esta ideia','plan-home','secondary')}</div></article><article class="card"><h3>Um passo de cada vez</h3><div class="line-item"><span class="round">✓</span><div><strong>Seus sentimentos, nas suas palavras</strong><small>Você revisa e escolhe o que compartilhar.</small></div></div><div class="line-item"><span class="round">◷</span><div><strong>Espaço para respirar</strong><small>Uma pausa pode ter um momento de retorno.</small></div></div><div class="line-item"><span class="round">♡</span><div><strong>Mais do que conversas difíceis</strong><small>Reconhecer o que faz bem também aproxima.</small></div></div></article></div>`}
function agreements(){return head('CLAREZA PARA NÓS','Nossos combinados','Um pedido vira combinado quando os dois concordam.',btn('+ Propor combinado','add-agreement'))+`<div class="stack">${state.agreements.map(a=>`<article class="card agreement"><div class="card-icon">${a.accepted.length===2?'✓':'◷'}</div><div class="body"><span class="badge ${a.accepted.length<2?'warm':''}">${a.rejected?'Não aceito neste momento':a.accepted.length===2?'Aceito pelos dois':'Proposta · aguardando '+esc(a.accepted.includes(me())?other():me())}</span><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><div class="meta"><span>Proposto por ${a.author}</span><span>${a.accepted.map(esc).join(' e ')} ${a.accepted.length===2?'concordaram':'concordou'}</span>${a.review?`<span>Revisar em ${esc(a.review.split('-').reverse().join('/'))}</span>`:''}</div></div>${agreementNegotiation(a)}</article>`).join('')}</div><p class="privacy">Os exemplos são fictícios. Alterar um combinado cria uma nova proposta para os dois avaliarem.</p>`}
const types=['Palavras de carinho','Tempo juntos','Apoio na rotina','Presentes e lembranças','Contato físico'];
function preferenceRecords(){return state.preferences.filter(p=>p.person===prefTab&&(prefTab===me()||p.shared!==false))}
function preferenceCard(p){const mine=prefTab===me();return `<article class="preference-item">${p.type?`<div class="preference-category">${esc(p.type)}</div>`:''}<p class="preference-quote">${esc(p.text)}</p>${p.frequency?`<span class="preference-frequency">${esc(p.frequency)}</span>`:''}${p.request?`<div class="request-detail"><span>Meu pedido <small>· para conversar</small></span><p>${esc(p.request)}</p></div>`:''}${mine?`<div class="preference-item-actions"><span class="visibility-label">${p.shared===false?'Só no meu perfil':'Compartilhado'}</span>${btn('Editar','pref-edit:'+p.id,'secondary')}${p.request?btn('Preparar mensagem','pref-message:'+p.id,'secondary'):''}${btn('Remover','delete-pref:'+p.id,'text-btn')}</div>`:''}</article>`}
function preferencePanel(level){const mine=prefTab===me(),important=level==='important',list=preferenceRecords().filter(p=>(p.level||'wellbeing')===level);return `<section class="preference-panel ${important?'important-panel':'wellbeing-panel'}"><div class="preference-panel-head"><span class="panel-symbol" aria-hidden="true">${important?'◇':'♡'}</span><h2>${important?'Importante para mim':'Me faz bem'}</h2><span class="preference-count">${list.length}</span></div><div class="preference-items">${list.map(preferenceCard).join('')||`<div class="preference-empty"><span aria-hidden="true">${important?'◇':'♡'}</span><p>${mine?(important?'O que tem mais peso para você?':'Que cuidado faz diferença?'):'Nada compartilhado por aqui ainda.'}</p></div>`}</div>${mine?btn(important?'+ Adicionar algo importante':'+ Adicionar um cuidado','pref-new:'+level,'panel-add secondary'):''}</section>`}
function legacyPreferences(){const mine=prefTab===me(),list=(state.avoidances||[]).filter(p=>p.person===prefTab&&(mine||p.shared!==false));if(!list.length)return '';return `<details class="preference-quiz legacy-preferences"><summary>${mine?'Revisar registros anteriores':'Registros anteriores compartilhados'} <span>${list.length}</span></summary>${mine?'<p class="helper">Você escolhe onde cada registro se encaixa.</p>':''}${list.map(p=>`<article class="preference-item"><p class="preference-quote">${esc(p.text)}</p>${p.need?`<p>${esc(p.need)}</p>`:''}${p.request?`<div class="request-detail"><span>Meu pedido</span><p>${esc(p.request)}</p></div>`:''}${mine?`<div class="actions">${btn('Revisar e escolher seção','pref-legacy:'+p.id,'secondary')}</div>`:''}</article>`).join('')}</details>`}
function preferences(){const mine=prefTab===me(),quiz=(mine||state.quizVisibility?.[prefTab]!==false)?state.quiz[prefTab]:null;return `<section class="preferences-page"><div class="preference-page-heading"><span class="eyebrow">CADA PESSOA TEM SEU JEITO</span><h1>${mine?'Meu jeito':'O jeito de '+esc(prefTab)}</h1><p>${mine?'O que importa. O que faz bem.':'Compartilhado por '+esc(prefTab)}</p></div><div class="preferences-board">${preferencePanel('important')}${preferencePanel('wellbeing')}</div>${legacyPreferences()}<div class="preference-bottom">${mine?btn('Descobrir meu jeito de receber carinho','quiz','secondary'):''}<button class="text-btn" data-action="evidence">Sobre este exercício</button></div>${quiz?`<details class="preference-quiz"><summary>Jeitos de receber carinho <span>Ver resultado →</span></summary><div class="card">${quiz.map(r=>`<div class="result-row"><strong>${esc(r.type)}</strong><span style="float:right">${r.score}/5</span><div class="bar"><span style="width:${r.score*20}%"></span></div></div>`).join('')}<p class="helper">Preferências de hoje, sem rótulos.</p></div>${sharingControls()}</details>`:''}</section>`}
let preferenceDraft=null;
function preferenceEditor(record={},legacy=false){preferenceDraft={...record,legacy:legacy||record.legacy||false,level:record.level||(record.id&&!legacy?'wellbeing':''),text:legacy?(record.need||''):record.text||'',origin:legacy?record.text:record.origin||'',shared:record.id?record.shared!==false:false};const d=preferenceDraft;modal(`<div class="eyebrow">NAS SUAS PALAVRAS</div><h2>${record.id?'Revisar meu registro':'O que você gostaria de contar?'}</h2><form id="preference-editor"><label class="field">Onde isso se encaixa?<select name="level" required><option value="">Escolher seção</option><option value="important" ${d.level==='important'?'selected':''}>Importante para mim — tem um peso maior</option><option value="wellbeing" ${d.level==='wellbeing'?'selected':''}>Me faz bem — gostaria que fosse assim</option></select></label><label class="field">O que é importante ou faz bem para mim<textarea name="text" required maxlength="1500" placeholder="Ex.: ter um tempo só nosso aos domingos.">${esc(d.text)}</textarea></label><details class="concern-guide" ${legacy?'open':''}><summary>Quero começar pelo que me incomoda</summary><label class="field">O que está acontecendo?<textarea name="origin" maxlength="1500" placeholder="Ex.: não gosto que você jogue bola todos os domingos.">${esc(d.origin)}</textarea></label><p class="helper">O que você gostaria de viver no lugar disso? Escreva no campo acima. Um limite também pode ser dito diretamente.</p><div class="note"><strong>Exemplos para pensar</strong><p>“Ter mais tempo juntos aos domingos.”</p><p>“Não quero brincadeiras sobre mim em público.”</p></div><p class="helper">Ajuda guiada, sem IA conectada. Este contexto não aparece no cartão do parceiro.</p></details><details class="preference-extra" ${d.request||d.frequency?'open':''}><summary>Adicionar pedido ou frequência</summary><label class="field">Meu pedido (opcional)<textarea name="request" maxlength="2000" placeholder="Ex.: podemos reservar dois domingos por mês para nós?">${esc(d.request||'')}</textarea></label><label class="field">Quando? (opcional)<input name="frequency" maxlength="160" value="${esc(d.frequency||'')}" placeholder="Ex.: aos domingos"></label></details><label class="check-label"><input type="checkbox" name="shared" ${d.shared?'checked':''}>Compartilhar este cartão com ${other()}</label><p class="helper">No protótipo, quem usa este navegador pode acessar os dois perfis.</p><div class="actions"><button class="btn">Revisar →</button></div></form>`);$('#preference-editor').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);preferenceDraft={...d,level:f.get('level'),text:f.get('text').trim(),origin:f.get('origin').trim(),request:f.get('request').trim(),frequency:f.get('frequency').trim(),shared:f.has('shared')};if(!preferenceDraft.text||!preferenceDraft.level)return;preferenceReview()}}
function preferenceReview(){const d=preferenceDraft;modal(`<div class="eyebrow">REVISAR ANTES DE SALVAR</div><h2>${d.level==='important'?'Importante para mim':'Me faz bem'}</h2><p class="message-body preference-quote">${esc(d.text)}</p>${d.frequency?`<span class="preference-frequency">${esc(d.frequency)}</span>`:''}${d.request?`<div class="request-detail"><span>Meu pedido · para conversar</span><p>${esc(d.request)}</p></div>`:''}<p class="helper">${d.shared?'Este cartão ficará visível para '+other()+'.':'Este cartão ficará só no seu perfil.'} Nenhuma mensagem será enviada.${d.origin?' O contexto inicial não será mostrado no cartão compartilhado.':''}</p><div class="actions">${btn('Editar','pref-back','secondary')}${btn(d.shared?'Salvar e compartilhar':'Salvar só no meu perfil','pref-save')}</div>`)}
function preferenceActions(a,id){if(a==='pref-new')preferenceEditor({level:id});if(a==='pref-edit'){const p=state.preferences.find(p=>p.id===id&&p.person===me());if(p)preferenceEditor(p)}if(a==='pref-legacy'){const p=(state.avoidances||[]).find(p=>p.id===id&&p.person===me());if(p)preferenceEditor(p,true)}if(a==='pref-back'&&preferenceDraft){const d=preferenceDraft;preferenceEditor({...d,id:d.id,origin:d.origin},false);preferenceDraft.legacy=d.legacy}if(a==='pref-save'&&preferenceDraft){const d=preferenceDraft,record={id:d.legacy?uid():d.id||uid(),person:me(),text:d.text,origin:d.origin,request:d.request,frequency:d.frequency,level:d.level,shared:d.shared,type:d.type||''},index=state.preferences.findIndex(p=>p.id===record.id&&p.person===me());if(index>=0)state.preferences[index]=record;else state.preferences.push(record);if(d.legacy)state.avoidances=(state.avoidances||[]).filter(p=>p.id!==d.id||p.person!==me());save();close();render();toast('Registro salvo.');preferenceDraft=null}if(a==='pref-message'){const p=state.preferences.find(p=>p.id===id&&p.person===me());if(!p?.request)return;flow={step:4,type:'Uma necessidade',answers:[p.text,'','',p.request],category:'Uma necessidade ou desejo',final:(p.level==='important'?'Algo importante para mim: ':'Algo que me faz bem: ')+p.text+'\n\nO que gostaria de pedir: '+p.request};page='comunicar';location.hash='comunicar';render();window.scrollTo(0,0)}}

const questions=[['Palavras de carinho','Ouvir palavras específicas de reconhecimento me faz sentir amado(a).'],['Tempo juntos','Ter um tempo de atenção, sem distrações, faz diferença para mim.'],['Apoio na rotina','Receber ajuda concreta com responsabilidades me faz sentir cuidado(a).'],['Presentes e lembranças','Uma pequena lembrança escolhida pensando em mim me toca.'],['Contato físico','Um abraço ou carinho, quando eu quero, me faz sentir próximo(a).'],['Palavras de carinho','Gosto de receber mensagens espontâneas de afeto.'],['Tempo juntos','Compartilhar um passeio ou uma atividade tranquila me aproxima do parceiro.'],['Apoio na rotina','Quando meu parceiro toma iniciativa para dividir tarefas, sinto apoio.'],['Presentes e lembranças','Gosto de pequenos gestos de surpresa, mesmo sem custo.'],['Contato físico','Valorizo demonstrações de afeto físico que respeitam meus limites.']];
function quizPage(){if(quizStep===questions.length){const results=types.map(type=>({type,score:questions.reduce((s,q,i)=>s+(q[0]===type?quizAnswers[i]:0),0)/2})).sort((a,b)=>b.score-a.score);return head('SEU MAPA DE CARINHO','Vários jeitos de se sentir amado(a).','O resultado descreve suas respostas de hoje. Você pode voltar e ajustar.')+`<div class="card form-card">${results.map(r=>`<div class="result-row"><strong>${r.type}</strong><span style="float:right">${r.score}/5</span><div class="bar"><span style="width:${r.score*20}%"></span></div></div>`).join('')}<p class="helper">Não há uma categoria que exclua as outras. Estas respostas ficam privadas até você escolher compartilhá-las no perfil de demonstração.</p><div class="actions">${btn('Revisar respostas','quiz-back','secondary')}${btn('Guardar resultado privado','quiz-private','secondary')}${btn('Compartilhar minhas preferências','quiz-share')}</div></div>`}return head('UM EXERCÍCIO DE AUTOCONHECIMENTO','Como o carinho chega até você?','São 10 perguntas sobre suas preferências de hoje. Ao final, você escolhe guardar o resultado ou compartilhá-lo.')+`<section class="card form-card"><div class="steps">${questions.map((q,i)=>`<span class="step ${i<=quizStep?'on':''}"></span>`).join('')}</div><div class="eyebrow">PERGUNTA ${quizStep+1} DE ${questions.length}</div><h2 style="margin-top:24px">${questions[quizStep][1]}</h2><p class="helper">Quanto essa afirmação combina com você?</p><div class="rating-row">${[1,2,3,4,5].map(v=>`<button class="${quizAnswers[quizStep]===v?'selected':''}" data-action="rate:${v}" aria-label="${v} de 5">${v}</button>`).join('')}</div><div style="display:flex;justify-content:space-between" class="mini-note"><span>Combina pouco comigo</span><span>Combina muito comigo</span></div><div class="actions">${btn('Voltar','quiz-back','secondary')}<button class="btn" data-action="quiz-next" ${!quizAnswers[quizStep]?'disabled':''}>${quizStep===9?'Ver meu mapa':'Continuar'} →</button></div><p class="mini-note">Exercício original de preferências; não é um teste psicológico validado.</p></section>`}
function communicate(){if(flow?.quiz)return quizPage();if(!flow)return head('ENCONTRAR AS PALAVRAS','O que você quer comunicar?','Pode ser algo difícil, um pedido ou um momento bom. Você escolhe o ritmo.')+`<div class="grid three">${[['Algo difícil','☁','Uma situação me machucou e quero me expressar.'],['Uma necessidade','♡','Gostaria de pedir algo que me faria bem.'],['Algo bom','✧','Quero reconhecer um gesto e dizer como me senti.']].map(([t,i,d])=>`<button class="card choice" data-action="start:${t}"><div class="card-icon">${i}</div><h3>${t}</h3><p>${d}</p><span class="card-link">Começar com calma <span>→</span></span></button>`).join('')}</div><div class="note" style="margin-top:26px">Seu rascunho não é enviado automaticamente. Você revisa tudo antes de compartilhar. Nesta demonstração, a organização do texto usa um roteiro, sem IA conectada.</div>`;
const n=flow.step;const prompts=[['Primeiro, o que aconteceu?','Descreva uma situação concreta, como você a percebeu. Não precisa encontrar as palavras perfeitas.','Ex.: durante o jantar, você olhou para o celular enquanto eu falava.'],['O que você sentiu?','Use suas palavras. Se ainda não souber, pode escrever isso também.','Ex.: senti tristeza e dificuldade para continuar falando.'],['O que gostaria que fosse compreendido?','Qual parte dessa experiência importa para você? Não precisamos adivinhar a intenção do outro.','Ex.: para mim, ter atenção nesse momento significa proximidade.'],['O que você gostaria de pedir ou dizer?','Pode ser uma conversa, um gesto, um agradecimento ou um pouco de tempo.','Ex.: gostaria de conversar sobre como podemos ter esse momento juntos.']];if(n<4){const q=prompts[n];return head('REFLEXÃO GUIADA · '+flow.type,q[0],q[1])+`<div class="card form-card"><div class="steps">${[0,1,2,3,4].map(i=>`<span class="step ${i<=n?'on':''}"></span>`).join('')}</div><label class="field">${['A situação','Meu sentimento','O significado para mim','Meu pedido ou reconhecimento'][n]}<textarea id="flow-input" placeholder="${q[2]}">${esc(flow.answers[n]||'')}</textarea></label>${n===1?`<div class="emotion-choices" aria-label="Palavras que podem ajudar">${['tristeza','raiva','medo','ciúme','vergonha','solidão','frustração','ainda não sei'].map(word=>btn(word,'emotion-word:'+word,'secondary')).join('')}</div><p class="helper">São palavras para explorar, não uma interpretação do que você sentiu. Escolha apenas se fizer sentido.</p>`:''}${n===0?`<p class="helper">Se preferir, registre somente o episódio atual. Você decide se mencionar outras situações ajuda a explicar o que viveu.</p>`:''}<div class="actions">${btn('Voltar','flow-back','secondary')}${btn('Continuar →','flow-next')}</div><p class="privacy">Este rascunho não é enviado ao parceiro. No protótipo, quem usa este navegador pode acessar os dois perfis.</p></div>`}return head('SUAS PALAVRAS, SUA ESCOLHA','Isso representa o que você sentiu?','A organização abaixo reúne o que você escreveu. Ajuste tudo o que desejar.')+`<section class="card form-card"><span class="badge">REVISÃO ANTES DE COMPARTILHAR</span><label class="field">Minha mensagem<textarea id="final-text" style="min-height:180px">${esc(flow.final||compose())}</textarea></label><label class="field">Você relaciona essa mensagem a quê?<select id="category">${['Ainda estou entendendo','Um combinado','Uma necessidade ou desejo','Reconhecimento'].map(c=>`<option ${flow.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Combinado relacionado (opcional)<select id="related"><option value="">Nenhum selecionado</option>${state.agreements.filter(a=>a.accepted.length===2).map(a=>`<option value="${a.id}" ${flow.related===a.id?'selected':''}>${esc(a.title)}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" id="confirm-send">Li a mensagem e quero enviá-la para ${other()} neste protótipo.</label><div class="actions">${btn('Voltar','flow-back','secondary')}${btn('Guardar rascunho','save-draft','secondary')}${btn('Enviar →','send')}</div><p class="privacy">Enviar simula a entrega apenas neste navegador. Nenhuma pessoa recebe uma notificação real.</p></section>`}
function compose(){const a=flow.answers;return `Quero compartilhar uma situação com você: ${a[0]}\n\nO que senti: ${a[1]}\n\nO que gostaria que você compreendesse: ${a[2]}\n\nO que gostaria de pedir ou dizer: ${a[3]}`}
function messages(){const tabs=`<div class="tabbar" role="group" aria-label="Filtrar conversas">${['Recebidas','Enviadas','Rascunhos'].map(t=>`<button class="tab ${t===msgTab?'active':''}" aria-pressed="${t===msgTab}" data-action="msg-tab:${t}">${t}</button>`).join('')}</div>`;const drafts=state.drafts.filter(d=>d.person===me());return head('TEMPO PARA DIZER E OUVIR','Conversas','Suas mensagens com '+other()+', com espaço para responder no seu ritmo.',btn('Preparar mensagem','new-message'))+tabs+`<div class="conversation-body">${msgTab==='Recebidas'?receivedMessages():msgTab==='Enviadas'?sentMessages():`<div class="stack">${drafts.length?drafts.map(d=>`<article class="card"><span class="badge">NÃO ENVIADO</span><p class="message-body">${esc(d.text)}</p><div class="actions">${btn('Continuar rascunho','draft:'+d.id)}${btn('Excluir rascunho','delete-draft:'+d.id,'secondary')}</div></article>`).join(''):'<div class="card empty">Seus rascunhos aparecerão aqui. Eles só são enviados quando você escolher compartilhar.</div>'}</div>`}</div><p class="privacy">Demonstração sem senha: quem usa este navegador pode acessar os dois perfis.</p>`}

const ideas={'Palavras de carinho':['Escreva uma mensagem contando uma qualidade que você admira em seu parceiro.','Agradeça por um gesto específico que fez diferença nesta semana.'],'Tempo juntos':['Convide para um jantar sem distrações. Pergunte qual dia seria bom para os dois.','Proponha uma caminhada tranquila, sem a obrigação de resolver assuntos difíceis.'],'Apoio na rotina':['Ofereça assumir uma tarefa concreta. Pergunte o que aliviaria o dia do seu parceiro.','Prepare algo que facilite a rotina de amanhã e conte sua intenção de cuidar.'],'Presentes e lembranças':['Deixe um bilhete ou uma pequena lembrança que tenha significado para vocês.','Pense em uma surpresa simples, respeitando o gosto e os limites do parceiro.'],'Contato físico':['Pergunte se um abraço seria bem-vindo agora. Respeite a resposta.','Convide para um momento de proximidade física que seja confortável para ambos.']};function suggestion(){const prefs=state.preferences.filter(p=>p.person===other());let p=prefs[0];const quiz=state.quizVisibility?.[other()]===false?null:state.quiz[other()];let type=quiz?.[0]?.type||p?.type||'Tempo juntos';return {type,text:ideas[type][0],pref:p?.text}}
function initiativePeriod(period,now=new Date()){return period==='dia'?new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime():period==='semana'?new Date(now.getFullYear(),now.getMonth(),now.getDate()-((now.getDay()+6)%7)).getTime():new Date(now.getFullYear(),now.getMonth(),1).getTime()}
function initiatives(){const list=(state.initiatives||[]).filter(g=>g.person===me());return list.length?`<div class="section-heading"><h2>Minhas iniciativas</h2><span class="badge">PESSOAIS</span></div><div class="investment-goals">${list.map(g=>{const count=(g.logs||[]).filter(t=>t>=initiativePeriod(g.period)).length,period={dia:'hoje',semana:'nesta semana',mes:'neste mês'}[g.period],percent=Math.min(100,count/g.target*100);return `<article class="card investment-goal"><div class="investment-goal-top"><span class="investment-action-icon">${investmentIcon('heart')}</span><span class="badge ${g.paused?'warm':''}">${g.paused?'Em pausa':'Em prática'}</span></div><h3>${esc(g.title)}</h3><div class="investment-count"><strong>${count}</strong><span>/ ${g.target} ${period}</span></div><div class="investment-progress" role="progressbar" aria-label="Registros da intenção ${esc(g.title)}" aria-valuemin="0" aria-valuemax="${g.target}" aria-valuenow="${Math.min(count,g.target)}"><span style="width:${percent}%"></span></div><p>${g.paused?'Retome quando desejar.':count>=g.target?'Você realizou o que planejou.':'Um gesto de cada vez.'}</p>${g.paused?btn('Retomar iniciativa','pause-intention:'+g.id,'secondary'):btn('＋ Realizei um gesto','log-intention:'+g.id)}<details class="investment-options"><summary>Ajustar iniciativa</summary><div class="actions">${btn('Editar','edit-intention:'+g.id,'secondary')}${!g.paused?btn('Pausar','pause-intention:'+g.id,'secondary'):''}${g.logs?.length?btn('Desfazer último registro','undo-intention:'+g.id,'secondary'):''}</div></details></article>`}).join('')}</div>`:''}
function investmentAction(a,id){if(a==='investment-log'){const list=(state.initiatives||[]).filter(g=>g.person===me()&&!g.paused);if(!list.length){intentionAction('add-intention');toast('Crie uma iniciativa para começar a registrar seus gestos.');return}modal(`<h2>Qual iniciativa você realizou?</h2><div class="stack">${list.map(g=>btn(esc(g.title),'log-intention:'+g.id,'secondary')).join('')}</div>`)}if(a==='investment-template'){const t={jantar:['Propor um jantar a dois',1,'mes'],carinho:['Oferecer um gesto de carinho',3,'mes'],atencao:['Reservar um momento de atenção',1,'dia']}[id];if(!t)return;intentionAction('add-intention');$('#intention-form input[name="title"]').value=t[0];$('#intention-form input[name="target"]').value=t[1];$('#intention-form select[name="period"]').value=t[2]}}

function intentionAction(a,id){const g=(state.initiatives||[]).find(g=>g.id===id&&g.person===me());if(a==='add-intention'||a==='edit-intention'){if(a==='edit-intention'&&!g)return;modal(`<div class="eyebrow">MINHAS INICIATIVAS · ${me()}</div><h2>${g?'Ajustar minha intenção':'Um cuidado que quero oferecer'}</h2><p>Escolha uma ação que depende da sua iniciativa, como propor um passeio ou demonstrar carinho.</p><form id="intention-form"><label class="field">O que quero oferecer?<input type="text" name="title" maxlength="180" required value="${esc(g?.title||'')}" placeholder="Ex.: propor um jantar a dois"></label><label class="field">Quantas vezes?<input type="number" name="target" min="1" max="100" required value="${g?.target||1}" style="padding:12px;border:1px solid var(--line);border-radius:8px"></label><label class="field">Em qual período?<select name="period">${[['mes','Por mês'],['semana','Por semana'],['dia','Por dia']].map(([v,t])=>`<option value="${v}" ${g?.period===v?'selected':''}>${t}</option>`).join('')}</select></label><p class="helper">Não envia notificações ao parceiro nem pede confirmação dele. ${g?'Se mudar o período, os registros serão contados na nova janela de calendário.':''}</p><div class="actions"><button class="btn">Salvar intenção pessoal</button></div></form>`);$('#intention-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),target=Number(f.get('target')),period=f.get('period');if(!title||!Number.isInteger(target)||target<1||target>100||!['dia','semana','mes'].includes(period))return;if(g){g.title=title;g.target=target;g.period=period}else{state.initiatives??=[];state.initiatives.push({id:uid(),person:me(),title,target,period,logs:[],paused:false})}save();close();render();toast('Intenção pessoal salva.')}}if(!g)return;if(a==='log-intention'){if(g.paused)return;modal(`<h2>Um gesto realizado</h2><p>Você realizou uma iniciativa de cuidado relacionada a “${esc(g.title)}”?</p><p class="helper">Este registro é seu. Não pede resposta ou retribuição do parceiro.</p><div class="actions">${btn('Confirmar registro','confirm-intention:'+g.id)}</div>`)}if(a==='confirm-intention'){if(g.paused)return;g.logs??=[];g.logs.push(Date.now());save();close();render();toast('Gesto registrado na sua intenção pessoal.')}if(a==='pause-intention'){g.paused=!g.paused;save();render()}if(a==='undo-intention'){g.logs?.pop();save();render();toast('Último registro desfeito.')}}


function dayKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function invitationDate(m){if(m.eventDate)return m.eventDate;const x=m.text.match(/Horário sugerido:\s*(\d{2})\/(\d{2})\/(\d{4})[, ]+(\d{2}):(\d{2})/);return x?`${x[3]}-${x[2]}-${x[1]}T${x[4]}:${x[5]}`:''}
function agendaEvents(){return [...state.messages.filter(m=>m.category==='Convite'&&invitationDate(m)&&m.inviteStatus!=='declined').map(m=>({id:'i'+m.id,sourceId:m.id,kind:'Convite',title:m.text.split('\n\nHorário sugerido:')[0],date:invitationDate(m),confirmed:m.inviteStatus==='accepted',from:m.from,to:m.to})),...state.messages.filter(m=>m.returnAt&&!m.reconnected).map(m=>({id:'r'+m.id,sourceId:m.id,kind:'Conversa',title:'Retomar conversa',date:m.returnAt,confirmed:!!m.returnAccepted,from:m.to,to:m.from})),...state.agreements.filter(a=>a.review&&a.accepted.length===2).map(a=>({id:'a'+a.id,sourceId:a.id,kind:'Revisão',title:a.title,date:a.review,confirmed:true})),...(agendaPersonal?state.planned.filter(p=>p.person===me()&&p.date).map(p=>({id:'p'+p.id,kind:'Só eu vejo',title:p.text,date:p.date,confirmed:true,personal:true})):[])].filter(e=>!isNaN(new Date(e.date).getTime())).sort((a,b)=>new Date(a.date)-new Date(b.date))}
function agenda(){const events=agendaEvents(),year=agendaMonth.getFullYear(),month=agendaMonth.getMonth(),start=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),selected=agendaDay?events.filter(e=>e.date.slice(0,10)===agendaDay):events.filter(e=>e.date.slice(0,10)>=dayKey(new Date())),undated=state.messages.filter(m=>m.category==='Convite'&&!invitationDate(m)&&m.inviteStatus!=='declined');return head('UM TEMPO PARA NÓS','Nossa agenda','Convites, reencontros e combinados em um só lugar.',btn('+ Agendar momento','agenda-add'))+messageNotice()+`<div class="agenda-layout"><section class="card agenda-calendar"><div class="agenda-toolbar">${btn('←','agenda-prev','secondary')}<h2>${esc(agendaMonth.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))}</h2>${btn('→','agenda-next','secondary')}</div><div class="agenda-week">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=>'<span>'+d+'</span>').join('')}</div><div class="agenda-days">${Array.from({length:start},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const key=dayKey(new Date(year,month,i+1)),items=events.filter(e=>e.date.slice(0,10)===key);return `<button class="agenda-day ${key===agendaDay?'selected':''} ${key===dayKey(new Date())?'today':''}" data-action="agenda-day:${key}" aria-label="${i+1} de ${esc(agendaMonth.toLocaleDateString('pt-BR',{month:'long'}))}, ${items.length} eventos" ${key===agendaDay?'aria-pressed="true"':''}><span>${i+1}</span><span class="agenda-dots">${items.slice(0,3).map(e=>`<i class="${e.personal?'personal':e.confirmed?'confirmed':'proposed'}"></i>`).join('')}</span></button>`}).join('')}</div><div class="agenda-legend"><span>● Confirmado</span><span>○ Proposto</span><span>◈ Pessoal</span></div><label class="check-label"><input type="checkbox" id="agenda-personal" ${agendaPersonal?'checked':''}> Mostrar meus lembretes pessoais</label><div class="actions">${btn('Hoje','agenda-today','secondary')}${btn('Ver próximos eventos','agenda-clear','secondary')}</div></section><section><div class="section-heading" style="margin-top:0"><h2>${agendaDay?esc(new Date(agendaDay+'T12:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long'})):'O que vem a seguir'}</h2></div><div class="stack">${selected.length?selected.map(e=>`<button class="card choice agenda-event" data-action="agenda-event:${e.id}"><span class="badge ${!e.confirmed?'warm':''}">${esc(e.kind)} · ${e.personal?'Pessoal':e.confirmed?'Confirmado':'Proposto'}</span><h3>${esc(e.title)}</h3><p>${esc(new Date(e.date.length===10?e.date+'T12:00':e.date).toLocaleDateString('pt-BR',{day:'numeric',month:'long'}))}${e.date.length>10?' · '+esc(new Date(e.date).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})):' · sem horário'}</p>${e.personal?'<small>Só aparece no seu perfil</small>':e.to?'<small>'+esc(e.from)+' → '+esc(e.to)+'</small>':''}</button>`).join(''):'<div class="card empty">Nenhum evento para este período.</div>'}</div></section></div>${undated.length?`<div class="section-heading"><h2>Convites sem data</h2></div><div class="stack">${undated.map(m=>`<article class="card"><h3>${esc(m.text)}</h3><p>A data ainda precisa ser combinada.</p>${btn('Ver convites','agenda-invites','secondary')}</article>`).join('')}</div>`:''}<p class="privacy">Tudo funciona neste navegador, com perfis de demonstração. Google Agenda, e-mail, WhatsApp e notificações no celular ainda não estão conectados. A passagem da data não marca um encontro como realizado.</p>`}
function agendaAction(a,id){if(a==='agenda-prev'||a==='agenda-next'){agendaMonth=new Date(agendaMonth.getFullYear(),agendaMonth.getMonth()+(a==='agenda-prev'?-1:1),1);render()}if(a==='agenda-day'){agendaDay=id;render()}if(a==='agenda-clear'){agendaDay='';render()}if(a==='agenda-today'){agendaMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);agendaDay=dayKey(new Date());render()}if(a==='agenda-invites')go('cuidar');if(a==='agenda-event'){const e=agendaEvents().find(e=>e.id===id);if(!e)return;modal(`<div class="eyebrow">${esc(e.kind)}</div><h2>${esc(e.title)}</h2><p>${esc(e.date.length===10?new Date(e.date+'T12:00').toLocaleDateString('pt-BR'):new Date(e.date).toLocaleString('pt-BR'))}</p><p>${e.personal?'Lembrete pessoal, visível somente neste perfil.':e.confirmed?'Horário confirmado. O encontro ainda não foi registrado como realizado.':'Horário proposto, aguardando confirmação.'}</p><div class="actions">${e.kind==='Convite'&&e.to===me()&&!e.confirmed?btn('Aceitar convite','agenda-accept:'+e.sourceId):''}${e.kind==='Conversa'&&e.to===me()&&!e.confirmed?btn('Confirmar horário','agenda-return:'+e.sourceId):''}${e.kind==='Revisão'?btn('Ver combinado','agreement:'+e.sourceId,'secondary'):''}${e.kind==='Conversa'||e.kind==='Convite'?btn('Ver conversa','agenda-messages','secondary'):''}</div>`)}if(a==='agenda-accept'){close();connectionAction('invite-accept',id)}if(a==='agenda-return'){const m=state.messages.find(m=>m.id===id&&m.from===me());if(m){m.returnAccepted=true;save();close();render();toast('Horário de retomada confirmado.')}}if(a==='agenda-messages'){close();msgTab='Recebidas';go('conversas')}if(a==='agenda-add'){modal(`<div class="eyebrow">RESERVAR UM MOMENTO</div><h2>O que vamos agendar?</h2><form id="agenda-form"><label class="field">Título<input type="text" name="title" required maxlength="180" placeholder="Ex.: jantar a dois"></label><label class="field">Data e horário<input type="datetime-local" name="date" required value="${agendaDay?agendaDay+'T19:00':''}"></label><label class="field">Visibilidade<select name="visibility"><option value="shared">Convite para ${other()}</option><option value="personal">Lembrete pessoal · só eu vejo</option></select></label><p class="helper">Um convite só aparece confirmado quando o outro perfil aceita. Lembretes pessoais não são compartilhados.</p><div class="actions"><button class="btn">Salvar na agenda</button></div></form>`);$('#agenda-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),date=f.get('date');if(!title||!date)return;if(new Date(date)<=new Date())return toast('Escolha um horário futuro.');if(f.get('visibility')==='personal')state.planned.push({id:uid(),person:me(),text:title,date});else state.messages.push({id:uid(),from:me(),to:other(),text:title,eventDate:date,type:'Algo bom',category:'Convite',status:'Enviada',created:Date.now()});agendaMonth=new Date(new Date(date).getFullYear(),new Date(date).getMonth(),1);agendaDay=date.slice(0,10);save();close();render();toast('Evento salvo na agenda de demonstração.')}}}

function biblical(){const enabled=state.faithEnabled?.[me()]!==false;const themes=[['Um tempo para ouvir','Tiago 1:19; Provérbios 18:13','O que eu compreendi da experiência do outro? O que ainda preciso perguntar?','Senhor, ajuda-me a ouvir com atenção e a responder com verdade e cuidado.'],['Verdade com amor','Efésios 4:15; Provérbios 15:1','Como posso expressar o que vivi com clareza, sem esconder minha dor nem atacar a outra pessoa?','Senhor, ajuda-me a encontrar palavras honestas e respeitosas.'],['Cuidar por iniciativa própria','1 João 3:18; Gálatas 6:9','Qual gesto de cuidado posso escolher livremente hoje, respeitando também meus limites?','Senhor, ajuda-me a oferecer cuidado com sinceridade, sem transformar carinho em cobrança.'],['Quando o coração está cansado','Salmos 34:18; Mateus 11:28','O que estou sentindo? De que apoio preciso neste momento?','Senhor, acolhe o que sinto e ajuda-me a reconhecer quando preciso de descanso e apoio.']];return head('UM ESPAÇO PESSOAL DE FÉ','Fé e reflexão','Leitura, oração e perguntas para você refletir no seu ritmo.',btn(enabled?'Pausar sugestões':'Ativar sugestões','faith-toggle','secondary'))+`<div class="note">${enabled?'As sugestões estão disponíveis para o seu perfil.':'Você pausou as sugestões no seu perfil. Pode continuar acessando suas anotações.'} A leitura é opcional e não é requisito para conversar.</div>${enabled?`<div class="grid pref-grid" style="margin-top:24px">${themes.map(([title,refs,question,prayer])=>`<article class="card"><span class="eyebrow">LEITURA SUGERIDA</span><h2 style="margin:14px 0">${title}</h2><span class="badge">${refs}</span><p style="margin-top:18px">${question}</p><div class="tip"><p>Oração sugerida, escrita para este espaço:</p><p>${prayer} Amém.</p></div>${btn('Escrever minha reflexão','faith-note','secondary')}</article>`).join('')}</div>`:''}<div class="section-heading"><h2>Minhas reflexões</h2>${btn('+ Guardar reflexão','faith-note','secondary')}</div><div class="stack">${(state.faithNotes||[]).filter(n=>n.person===me()).slice().reverse().map(n=>`<article class="card"><span class="badge">PESSOAL · ${me()}</span><p class="message-body" style="margin-top:14px">${esc(n.text)}</p><small>${esc(new Date(n.created).toLocaleDateString('pt-BR'))}</small></article>`).join('')||'<div class="card empty">Suas anotações ficam neste perfil e não são enviadas ao parceiro.</div>'}</div><p class="privacy">Leia as passagens no contexto, na tradução de sua preferência. Perguntas e orações são propostas de reflexão, não citações bíblicas nem afirmações sobre a vontade de Deus para sua situação. Perdão não exige tolerar violência ou coerção. Se houver medo ou ameaça, priorize segurança e apoio individual. Este espaço não substitui acompanhamento profissional ou pastoral. A privacidade entre perfis ainda é demonstrativa, sem senha.</p>`}
function agreementNegotiation(x){if(x.rejected)return '<span class="badge warm">Não aceito neste momento</span>';return `<div class="actions">${!x.accepted.includes(me())?btn('Aceitar','accept:'+x.id,'secondary')+btn('Sugerir ajuste','negotiate:'+x.id,'secondary')+btn('Não agora','decline-agreement:'+x.id,'secondary'):btn('Ver detalhes','agreement:'+x.id,'secondary')}</div>${x.amendment?`<div class="note" style="margin-top:15px"><strong>Ajuste proposto por ${esc(x.amendment.person)}</strong><p>${esc(x.amendment.text)}</p><small>O texto anterior permanece registrado até ambos concordarem.</small>${x.amendment.person!==me()?`<div class="actions">${btn('Aceitar ajuste','approve-amendment:'+x.id,'secondary')}${btn('Manter texto anterior','reject-amendment:'+x.id,'secondary')}</div>`:'<small>Aguardando resposta do outro perfil.</small>'}</div>`:''}`}
function sharingControls(){if(prefTab===me()&&state.quiz[me()])return `<div class="card" style="margin-bottom:20px"><h3>Você controla o compartilhamento</h3><p>${state.quizVisibility?.[me()]===false?'Seu resultado está privado.':'Seu resultado está compartilhado com '+other()+'.'}</p>${btn(state.quizVisibility?.[me()]===false?'Compartilhar resultado':'Retirar compartilhamento','toggle-quiz-share','secondary')}</div>`;if(prefTab!==me()&&state.quiz[prefTab]&&state.quizVisibility?.[prefTab]!==false)return `<div class="card" style="margin-bottom:20px"><h3>Você compreendeu o que ${prefTab} valoriza?</h3><p>Uma abertura para esclarecer, sem avaliação ou nota.</p><div class="actions">${btn('Entendi','understood:entendi','secondary')}${btn('Quero entender melhor','understood:conversar','secondary')}</div>${state.quizUnderstanding?.[me()]?'<small>Sua resposta: '+esc(state.quizUnderstanding[me()])+'</small>':''}</div>`;return ''}
function faithAndSharingAction(a,id){if(a==='faith-toggle'){state.faithEnabled??={};state.faithEnabled[me()]=state.faithEnabled[me()]===false;save();render()}if(a==='faith-note'){modal(`<h2>Minha reflexão</h2><p>Este texto permanece no seu perfil e não será enviado ao parceiro.</p><form id="faith-form"><label class="field">O que gostaria de guardar?<textarea name="text" required maxlength="5000"></textarea></label><div class="actions"><button class="btn">Guardar no meu perfil</button></div></form>`);$('#faith-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;state.faithNotes??=[];state.faithNotes.push({id:uid(),person:me(),text,created:Date.now()});save();close();render();toast('Reflexão guardada no seu perfil.')}}if(a==='toggle-quiz-share'){state.quizVisibility??={};state.quizVisibility[me()]=state.quizVisibility[me()]===false;save();render();toast(state.quizVisibility[me()]?'Resultado compartilhado.':'Compartilhamento retirado.')}if(a==='understood'){state.quizUnderstanding??={};state.quizUnderstanding[me()]=id==='entendi'?'Entendi o que você valoriza':'Quero entender melhor';save();render()}if(a==='decline-agreement'){const x=state.agreements.find(x=>x.id===id);if(!x||x.accepted.includes(me()))return;x.rejected=true;save();render()}if(a==='negotiate'){const x=state.agreements.find(x=>x.id===id);if(!x)return;modal(`<h2>Sugerir um ajuste</h2><p>Texto atual: ${esc(x.description)}</p><form id="amendment-form"><label class="field">Qual texto você propõe?<textarea name="text" required maxlength="3000">${esc(x.description)}</textarea></label><p class="helper">O ajuste só vale após o aceite do outro perfil.</p><div class="actions"><button class="btn">Enviar proposta de ajuste</button></div></form>`);$('#amendment-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;x.amendment={person:me(),text};save();close();render();toast('Ajuste aguardando concordância.')}}if(a==='approve-amendment'||a==='reject-amendment'){const x=state.agreements.find(x=>x.id===id);if(!x?.amendment||x.amendment.person===me())return;if(a==='approve-amendment'){x.history??=[];x.history.push({description:x.description,accepted:[...x.accepted],created:Date.now()});x.description=x.amendment.text;x.accepted=['Melina','Fabien'];x.rejected=false;x.acceptedAt=Date.now()}x.amendment=null;save();render()}}

function care(){const s=suggestion(),moments=state.moments||[],pending=incoming(),returns=state.messages.filter(m=>m.returnAt&&!m.reconnected),last=moments.slice().sort((a,b)=>b.created-a.created)[0],prefs=state.preferences.filter(p=>p.person===other()),next=state.planned.filter(p=>p.person===me()&&p.date&&new Date(p.date)>new Date()).sort((a,b)=>new Date(a.date)-new Date(b.date))[0];return head('CUIDAR DE NÓS','Nosso espaço de conexão','Reconhecer o que faz bem. Dar atenção ao que ainda precisa de cuidado.')+`<section class="connection-intro"><span class="connection-mark" aria-hidden="true">⌒</span><div><h2>Pequenos cuidados criam proximidade.</h2><p class="sub">Um espaço para perceber os gestos, retomar conversas e escolher o próximo encontro.</p></div></section><div class="grid connection-grid"><article class="card connection-card"><div class="eyebrow">♡ O QUE NOS FEZ BEM</div><h2>${last?'Um cuidado reconhecido':'O carinho merece ser lembrado'}</h2><p>${last?'“'+esc(last.text)+'”':'Conte um momento em que você se sentiu amado(a), dentro ou fora do app.'}</p>${last?'<small>Compartilhado por '+esc(last.person)+'</small>':''}${btn('Registrar um momento bom →','good-moment','secondary')}</article><article class="card connection-card"><div class="eyebrow"><span class="chat-icon" aria-hidden="true"></span> O QUE PEDE ATENÇÃO</div><h2>${pending.length?pending.length===1?'Uma abertura para ouvir':pending.length+' mensagens para ouvir':returns.length?'Um momento para retomar':'Espaço para escutar'}</h2><p>${pending.length?'Há '+pending.length+' '+(pending.length===1?'mensagem aguardando':'mensagens aguardando')+' sua resposta. Você pode conversar ou propor outro momento.':returns.length?'Vocês propuseram um horário para conversar. Confirmem depois se conseguiram se reencontrar.':'Nenhuma mensagem sua está aguardando resposta neste momento. Vocês podem abrir uma nova conversa.'}</p>${btn(pending.length?'Ler e responder →':returns.length?'Ver retomadas →':'Preparar uma mensagem →',pending.length||returns.length?'open-inbox':'new-message','secondary')}</article><article class="card connection-card connection-wide"><div><div class="eyebrow">◷ UM MOMENTO PARA NÓS</div><h2>${next?'Um lembrete pessoal':'Um tempo só para vocês'}</h2><p>${next?esc(next.text)+' · '+esc(new Date(next.date).toLocaleString('pt-BR')):prefs[0]?other()+' compartilhou: “'+esc(prefs[0].text)+'”':'Que momento vocês gostariam de compartilhar?'}</p></div><a class="btn" href="#agenda">Ver nossa agenda →</a></article></div>${returns.length?`<div class="section-heading"><h2>Conversas com retorno proposto</h2></div><div class="stack">${returns.map(m=>`<article class="card"><span class="badge warm">RETOMADA PROPOSTA</span><p style="margin:14px 0">${esc(m.from)} e ${esc(m.to)} · ${esc(new Date(m.returnAt).toLocaleString('pt-BR'))}</p><p>O horário é uma proposta. Cada pessoa pode confirmar que a conversa aconteceu.</p>${(m.reconnectedBy||[]).includes(me())?'<small>Você já confirmou. Aguardando o outro perfil.</small>':btn('Conversamos neste retorno','reconnected:'+m.id,'secondary')}</article>`).join('')}</div>`:''}<div class="section-heading"><h2>Cuidados que vocês reconheceram</h2><span class="badge">SEM PONTOS OU METAS</span></div><div class="card connection-history">${connectionHistory()}</div>${invitationSection()}<div class="section-heading"><h2>Nossas orações</h2></div><article class="card"><p>Pedidos que vocês escolheram compartilhar, reunidos em um só lugar.</p><a class="btn secondary" href="#oracoes-casal">Ver pedidos compartilhados →</a></article><p class="privacy">Este espaço mostra apenas o que foi registrado. Ausência de registros não significa ausência de carinho. Mensagens e lembretes são simulados neste navegador.</p>`}
function invitationSection(){const list=state.messages.filter(m=>m.category==='Convite');return `<div class="section-heading"><h2>Convites e planos</h2>${btn('+ Fazer um convite','connection-invite','secondary')}</div><p class="helper">Propostas para viver algo juntos. Aceitar um convite não significa que o encontro já aconteceu.</p><div class="stack">${list.length?list.slice().reverse().map(m=>`<article class="card"><span class="badge ${!m.inviteStatus?'warm':''}">${m.inviteStatus==='accepted'?'CONVITE ACEITO':m.inviteStatus==='declined'?'NÃO COMBINADO':'AGUARDANDO RESPOSTA AO CONVITE'}</span><p class="message-body" style="margin:16px 0">${esc(m.text)}</p><small>${esc(m.from)} convidou ${esc(m.to)}</small><div class="actions">${m.to===me()&&!m.inviteStatus?btn('Aceitar convite','invite-accept:'+m.id,'secondary')+btn('Não posso desta vez','invite-decline:'+m.id,'secondary'):''}${btn('Ver conversa','open-inbox','secondary')}</div></article>`).join(''):'<div class="card empty">Os convites compartilhados aparecerão aqui.</div>'}</div>`}

function connectionHistory(){const events=[...(state.moments||[]).map(m=>({text:'“'+m.text+'”',detail:m.person+' contou que se sentiu cuidado(a)',time:m.created})),...state.messages.filter(m=>m.type==='Algo bom'&&m.category==='Reconhecimento').map(m=>({text:m.text,detail:m.from+' compartilhou algo bom com '+m.to,time:m.created})),...state.messages.filter(m=>m.reconnected).map(m=>({text:'Vocês retomaram uma conversa',detail:'Retorno confirmado pelos dois',time:m.reconnectedAt||0}))].sort((a,b)=>b.time-a.time);return events.length?events.map(e=>`<div class="line-item"><span class="round" aria-hidden="true">♡</span><div><strong>${esc(e.text)}</strong><small>${esc(e.detail)}${e.time?' · '+esc(new Date(e.time).toLocaleDateString('pt-BR')):''}</small></div></div>`).join(''):'<p>Os momentos de carinho reconhecidos aparecerão aqui.</p>'}
function connectionAction(a,id){if(a==='invite-accept'||a==='invite-decline'){const m=state.messages.find(m=>m.id===id&&m.to===me()&&m.category==='Convite');if(!m||m.inviteStatus)return;m.inviteStatus=a==='invite-accept'?'accepted':'declined';m.status=a==='invite-accept'?'Convite aceito':'Convite respondido';save();render();toast('Resposta ao convite registrada.');}if(a==='open-inbox'){msgTab='Recebidas';go('conversas')}if(a==='good-moment'){modal(`<div class="eyebrow">O QUE ME FEZ BEM</div><h2>Um cuidado que fez diferença</h2><p>Pode ter acontecido fora do app. Conte o gesto e como você se sentiu.</p><form id="moment-form"><label class="field">Meu momento<textarea name="text" required maxlength="2000" placeholder="Ex.: quando você preparou o jantar, me senti cuidada."></textarea></label><p class="helper">Ao registrar, este momento fica visível para os dois perfis da demonstração.</p><div class="actions"><button class="btn">Compartilhar momento</button></div></form>`);$('#moment-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;state.moments??=[];state.moments.push({id:uid(),person:me(),text,created:Date.now()});save();close();render();toast('Momento acrescentado ao histórico de cuidados.')}}if(a==='connection-invite'){modal(`<div class="eyebrow">UM MOMENTO PARA NÓS</div><h2>Um convite para ${other()}</h2><form id="invite-form"><label class="field">Qual é a sua ideia?<textarea name="text" required placeholder="Que tal caminharmos juntos neste fim de semana?"></textarea></label><label class="field">Horário sugerido (opcional)<input type="datetime-local" name="date"></label><p class="helper">É um convite, sem compromisso automático. O outro perfil poderá responder. O envio é simulado neste navegador.</p><div class="actions"><button class="btn">Compartilhar convite</button></div></form>`);$('#invite-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),text=f.get('text').trim(),date=f.get('date');if(!text)return;if(date&&new Date(date)<=new Date())return toast('Escolha um horário futuro.');state.messages.push({id:uid(),from:me(),to:other(),eventDate:date||'',text:text+(date?'\n\nHorário sugerido: '+new Date(date).toLocaleString('pt-BR'):''),type:'Algo bom',category:'Convite',status:'Enviada',created:Date.now()});save();close();render();toast('Convite registrado. O outro perfil pode responder em Conversas.')}}if(a==='reconnected'){const m=state.messages.find(m=>m.id===id);if(!m)return;m.reconnectedBy??=[];if(!m.reconnectedBy.includes(me()))m.reconnectedBy.push(me());if(m.reconnectedBy.includes(m.from)&&m.reconnectedBy.includes(m.to)){m.reconnected=true;m.reconnectedAt=Date.now()}save();render();toast(m.reconnected?'Retomada confirmada pelos dois.':'Sua confirmação foi registrada. Aguardando o outro perfil.')}}

function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();bind($('#modal-body'))}function close(){$('#modal').close()}
function formAgreement(a){modal(`<div class="eyebrow">CONSTRUIR EM CONJUNTO</div><h2>${a?'Propor uma nova versão':'Um combinado claro'}</h2><p>Definam uma ação possível. A proposta só entra em prática quando os dois aceitarem.</p><form id="agreement-form"><label class="field">Título<input name="title" required maxlength="100" value="${esc(a?.title||'')}" placeholder="Ex.: presença durante o jantar"></label><label class="field">O que estamos propondo?<textarea name="description" required placeholder="Quem fará o quê e em qual situação?">${esc(a?.description||'')}</textarea></label><label class="field">Quando revisar? (opcional)<input type="date" name="review" value="${esc(a?.review||'')}"></label><div class="actions"><button class="btn" type="submit">Salvar proposta</button></div></form>`);$('#agreement-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('title').trim()||!f.get('description').trim())return;state.agreements.push({id:uid(),title:f.get('title').trim(),description:f.get('description').trim(),review:f.get('review'),author:me(),accepted:[me()]});save();close();render();toast('Proposta criada. O outro perfil pode avaliar e aceitar.')}}
function bind(root=document){root.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action))}
function action(s){const [a,id,arg]=s.split(':');gestureAction(a,id);if(a.startsWith('pref-')){preferenceActions(a,id);return;}concernAction(a,id);connectionAction(a,id);intentionAction(a,id);agendaAction(a,id);faithAndSharingAction(a,id);prayerAction(a,id);investmentAction(a,id);coupleAction(a);partnerAction(a,id);aboutAction(a,id);threadAction(a,id);if(a==='new-message')go('comunicar');if(a==='add-agreement')formAgreement();if(a==='accept'){const x=state.agreements.find(a=>a.id===id);if(x.rejected)return;if(!x.accepted.includes(me()))x.accepted.push(me());if(x.accepted.length===2)x.acceptedAt=Date.now();save();render();toast('Combinado aceito pelos dois.')}if(a==='agreement'){const x=state.agreements.find(a=>a.id===id);modal(`<span class="badge">${x.accepted.length===2?'ACEITO PELOS DOIS':'PROPOSTA'}</span><h2 style="margin-top:18px">${esc(x.title)}</h2><p>${esc(x.description)}</p><p class="helper">Qualquer mudança deve ser proposta novamente. O acordo atual permanece registrado.</p>${btn('Negociar ajuste','negotiate:'+id,'secondary')}`)}if(a==='revise')formAgreement(state.agreements.find(x=>x.id===id));if(a==='pref'){prefTab=id;render()}if(a==='partner-pref'){prefTab=other();go('preferencias-parceiro')}if(a==='add-pref'){modal(`<div class="eyebrow">NAS SUAS PALAVRAS</div><h2>O que faz você se sentir cuidado(a)?</h2><form id="pref-form"><label class="field">Tipo de gesto<select name="type">${[...types,'Outro jeito de cuidar'].map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">Conte algo que você gosta<textarea name="text" required placeholder="Ex.: que me perguntem como estou e escutem com atenção."></textarea></label><label class="field">Em que momento ou frequência?<input name="frequency" type="text" placeholder="Ex.: no dia a dia, sem obrigação"></label><p class="helper">Ao salvar, esta preferência fica visível no perfil compartilhado da demonstração.</p><div class="actions"><button class="btn">Compartilhar preferência</button></div></form>`);$('#pref-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('text').trim())return;state.preferences.push({id:uid(),person:me(),type:f.get('type'),text:f.get('text').trim(),frequency:f.get('frequency')});save();close();render()}}if(a==='delete-pref'){state.preferences=state.preferences.filter(p=>p.id!==id||p.person!==me());save();render()}if(a==='quiz'){flow={quiz:true};quizStep=0;quizAnswers=[];page='comunicar';location.hash=page;render()}if(a==='rate'){quizAnswers[quizStep]=Number(id);render()}if(a==='quiz-next'&&quizAnswers[quizStep]){quizStep++;render()}if(a==='quiz-back'){if(quizStep>0){quizStep--;render()}else{flow=null;go('carinho')}}if(a==='quiz-share'||a==='quiz-private'){state.quizVisibility??={};state.quizVisibility[me()]=a==='quiz-share';state.quiz[me()]=types.map(type=>({type,score:questions.reduce((s,q,i)=>s+(q[0]===type?quizAnswers[i]:0),0)/2})).sort((a,b)=>b.score-a.score);save();prefTab=me();flow=null;go('carinho');toast('Mapa de preferências compartilhado neste protótipo.')}if(a==='start'){flow={step:0,type:id,answers:[],category:id==='Algo bom'?'Reconhecimento':'Ainda estou entendendo'};render()}if(a==='flow-next'){const t=$('#flow-input').value.trim();if(!t)return toast('Escreva algo ou diga que ainda não sabe.');flow.answers[flow.step]=t;flow.step++;render()}if(a==='flow-back'){if(flow.step===4){flow.final=$('#final-text').value;flow.category=$('#category').value;flow.related=$('#related').value}else flow.answers[flow.step]=$('#flow-input').value;if(flow.step>0)flow.step--;else flow=null;render()}if(a==='send'||a==='save-draft'){const text=$('#final-text').value.trim();if(!text)return toast('Revise a mensagem antes de continuar.');flow.final=text;flow.category=$('#category').value;flow.related=$('#related').value;if(a==='send'){if(!$('#confirm-send').checked)return toast('Confirme que deseja compartilhar a mensagem.');state.messages.push({id:uid(),from:me(),to:other(),text,type:flow.type,category:flow.category,related:flow.related,status:'Enviada',created:Date.now()});if(flow.draftId)state.drafts=state.drafts.filter(d=>d.id!==flow.draftId);msgTab='Enviadas';toast('Envio simulado. Troque o perfil para experimentar o recebimento.')}else{const d={id:flow.draftId||uid(),person:me(),text,flow:JSON.parse(JSON.stringify(flow))};state.drafts=state.drafts.filter(x=>x.id!==d.id);state.drafts.push(d);msgTab='Rascunhos';toast('Rascunho guardado neste navegador.')}save();flow=null;go('conversas')}if(a==='msg-tab'){msgTab=id;page='conversas';location.hash='conversas';render()}if(a==='draft'){const d=state.drafts.find(d=>d.id===id&&d.person===me());flow={...d.flow,draftId:d.id};page='comunicar';location.hash=page;render()}if(a==='delete-draft'){state.drafts=state.drafts.filter(d=>d.id!==id||d.person!==me());save();render()}if(a==='respond'){const m=state.messages.find(m=>m.id===id);const title={agora:'Posso conversar agora',tempo:'Preciso de um tempo',entender:'Quero entender melhor',carinho:'Enviar uma mensagem a '+m.from,ideia:'Sugerir uma ideia ou proposta'}[arg];modal(`<div class="eyebrow">RESPONDER A ${m.from.toUpperCase()}</div><h2>${title}</h2><form id="response-form"><label class="field">Sua resposta<textarea name="text" required placeholder="${arg==='ideia'?'Que tal propor um passeio ou um momento juntos?':'Escreva sua mensagem, nas suas palavras.'}">${arg==='carinho'||arg==='ideia'?'':arg==='agora'?'Recebi sua mensagem. Podemos conversar agora?':arg==='tempo'?'Recebi sua mensagem. Preciso organizar o que sinto e gostaria de propor um momento para conversarmos.':'Quero compreender melhor. Você pode me explicar um pouco mais sobre o que sentiu?'}</textarea></label>${arg==='tempo'?'<label class="field">Propor uma retomada<input name="returnAt" type="datetime-local" required></label>':''}<p class="helper">${arg==='carinho'?'Você escolhe como expressar seu carinho. Revise antes de compartilhar.':arg==='ideia'?'Sua ideia é um convite. Vocês podem decidir juntos se e quando faz sentido.':'A resposta não exige concordar com todos os pontos. O horário é uma proposta para vocês confirmarem.'}</p><div class="actions"><button class="btn">Compartilhar resposta</button></div></form>`);$('#response-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('text').trim())return;const dt=f.get('returnAt');if(dt&&new Date(dt)<=new Date())return toast('Escolha um horário futuro para a retomada.');m.response=f.get('text');m.respondedAt=Date.now();m.awaitingReplyFrom=m.from;m.returnAt=dt||'';m.returnAccepted=false;m.status=arg==='tempo'?'Retomada proposta':'Respondida';save();close();render();toast('Resposta registrada no protótipo.')}}if(a==='plan-home'){state.planned.push({id:uid(),person:me(),text:suggestion().text});save();if(page==='agradar'||page==='cuidar')render();toast('Ideia guardada em Demonstrar carinho.')}if(a==='delete-plan'){state.planned=state.planned.filter(p=>p.id!==id);save();render()}if(a==='reminder'){modal(`<h2>Um convite no seu ritmo</h2><form id="reminder-form"><label class="field">O que deseja lembrar?<input type="text" name="text" required placeholder="Ex.: convidar para uma caminhada"></label><label class="field">Quando?<input type="datetime-local" name="date" required></label><p class="helper">O lembrete fica na lista deste protótipo. Não há notificações externas.</p><div class="actions"><button class="btn">Guardar lembrete</button></div></form>`);$('#reminder-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('text').trim())return;state.planned.push({id:uid(),person:me(),text:f.get('text'),date:f.get('date')});save();close();render();toast('Lembrete guardado na lista.')}}if(a==='evidence')modal(`<h2>Preferências, sem rótulos</h2><p>Este exercício usa perguntas originais sobre formas de receber carinho. Não reproduz o questionário do livro e não é uma avaliação psicológica validada.</p><p>Uma revisão científica de 2024 encontrou pouco apoio para a ideia de uma linguagem principal fixa ou de que combinar linguagens garante relações melhores. Por isso, mostramos todas as preferências, que podem mudar.</p><p><a href="https://doi.org/10.1177/09637214231217663" target="_blank" rel="noopener">Ler a revisão de Impett, Park e Muise ↗</a></p>`)}
$('#profile').onchange=e=>{state.profile=e.target.value;flow=null;prefTab=me();save();render();toast('Você está experimentando o perfil de '+me()+'.')};$('#modal .close').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});$('#about').onclick=()=>modal(`<div class="eyebrow">ELOS</div><h2>Um espaço para nós dois.</h2><p>Este espaço é privado e serve apenas a vocês dois. Os dados são guardados no Firebase e aparecem nos dispositivos em que vocês entrarem com a própria conta Google.</p><p>Não há IA conectada nem envio de notificações. Os rascunhos e reflexões individuais ficam privados; só o que você aprovar é compartilhado.</p><p>Se houver medo, ameaça ou violência, priorize apoio individual e segurança; a conversa conjunta pode não ser adequada.</p>`);const hash=location.hash.slice(1);if(menu.some(x=>x[0]===hash))page=hash;render();

function coupleNextSteps(){const proposals=state.agreements.filter(a=>!a.rejected&&!a.accepted.includes(me()));return messageNotice()+(proposals.length?`<section class="note"><strong>${proposals.length===1?'Uma proposta de combinado espera sua avaliação':proposals.length+' propostas de combinado esperam sua avaliação'}</strong><p>Você pode aceitar ou conversar sobre um ajuste.</p><a class="btn secondary" href="#combinados">Avaliar propostas →</a></section>`:'')}
